// ==========================================================================
// 📅 Thai Calendar Popup Engine (ปฏิทินไทย พ.ศ.)
// ==========================================================================

const THAI_MONTHS_FULL = {
  'มกราคม': '01', 'กุมภาพันธ์': '02', 'มีนาคม': '03', 'เมษายน': '04',
  'พฤษภาคม': '05', 'มิถุนายน': '06', 'กรกฎาคม': '07', 'สิงหาคม': '08',
  'กันยายน': '09', 'ตุลาคม': '10', 'พฤศจิกายน': '11', 'ธันวาคม': '12'
};
const THAI_MONTHS_SHORT = {
  'ม.ค.': '01', 'ก.พ.': '02', 'มี.ค.': '03', 'เม.ย.': '04',
  'พ.ค.': '05', 'มิ.ย.': '06', 'ก.ค.': '07', 'ส.ค.': '08',
  'ก.ย.': '09', 'ต.ค.': '10', 'พ.ย.': '11', 'ธ.ค.': '12'
};
const THAI_MONTH_NAMES = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];

// State for the shared calendar popup
let _calState = { prefix: null, yearAD: 2026, month: 0 }; // month: 0-based

function _calHiddenId(prefix) {
  if (prefix === 'start' || prefix === 'end') return `form-${prefix}-date`;
  return `${prefix}-date-input`; // gdrive-date-input, weburl-date-input
}
function _calDisplayId(prefix) {
  return `cal-display-${prefix}`;
}
function _calBtnId(prefix) {
  if (prefix === 'start') return 'cal-btn-start';
  if (prefix === 'end') return 'cal-btn-end';
  return `cal-btn-${prefix}`;
}

function _isoToThaiDisplay(iso) {
  if (!iso) return 'เลือกวันที่...';
  const p = iso.split('-');
  if (p.length !== 3) return iso;
  const be = parseInt(p[0], 10) + 543;
  const day = parseInt(p[2], 10);
  const mn = THAI_MONTH_NAMES[parseInt(p[1], 10) - 1] || '';
  return `${day} ${mn} ${be}`;
}

function _renderCalDays() {
  const popup = document.getElementById('thai-cal-popup');
  if (!popup) return;
  const { yearAD, month } = _calState;
  const yearBE = yearAD + 543;

  // Update header selects
  const hMonth = document.getElementById('cal-header-month');
  const hYear = document.getElementById('cal-header-year');
  if (hMonth) hMonth.value = month;
  if (hYear) hYear.value = yearBE;

  // Which day is selected?
  const hiddenEl = document.getElementById(_calHiddenId(_calState.prefix));
  const selectedIso = hiddenEl ? hiddenEl.value : '';
  const selParts = selectedIso ? selectedIso.split('-') : [];
  const selY = selParts[0] ? parseInt(selParts[0]) : -1;
  const selM = selParts[1] ? parseInt(selParts[1]) - 1 : -1;
  const selD = selParts[2] ? parseInt(selParts[2]) : -1;

  // Today
  const todayAD = new Date();
  const tY = todayAD.getFullYear(), tM = todayAD.getMonth(), tD = todayAD.getDate();

  const firstDay = new Date(yearAD, month, 1).getDay(); // 0=Sun
  const daysInMonth = new Date(yearAD, month + 1, 0).getDate();

  const grid = document.getElementById('cal-days');
  if (!grid) return;
  grid.innerHTML = '';

  // Empty cells before 1st
  for (let i = 0; i < firstDay; i++) {
    const blank = document.createElement('div');
    grid.appendChild(blank);
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = d;
    const isSelected = (selY === yearAD && selM === month && selD === d);
    const isToday = (tY === yearAD && tM === month && tD === d);
    btn.style.cssText = `width:100%; aspect-ratio:1; border:none; border-radius:50%; cursor:pointer; font-size:0.78rem; font-weight: ${isToday ? '700' : '400'};
      background: ${isSelected ? 'var(--apple-blue)' : isToday ? 'rgba(0,113,227,0.18)' : 'transparent'};
      color: ${isSelected ? '#fff' : isToday ? 'var(--apple-blue)' : '#e5e5e7'};
      outline: ${isToday && !isSelected ? '1px solid rgba(0,113,227,0.4)' : 'none'};`;
    btn.onmouseenter = () => { if (!isSelected) btn.style.background = 'rgba(255,255,255,0.08)'; };
    btn.onmouseleave = () => { if (!isSelected) btn.style.background = isToday ? 'rgba(0,113,227,0.18)' : 'transparent'; };
    btn.onclick = () => _calSelectDay(d);
    grid.appendChild(btn);
  }
}

function _calSelectDay(day) {
  const { prefix, yearAD, month } = _calState;
  const mm = String(month + 1).padStart(2, '0');
  const dd = String(day).padStart(2, '0');
  const iso = `${yearAD}-${mm}-${dd}`;

  const hiddenEl = document.getElementById(_calHiddenId(prefix));
  if (hiddenEl) hiddenEl.value = iso;

  const displayEl = document.getElementById(_calDisplayId(prefix));
  if (displayEl) {
    displayEl.textContent = _isoToThaiDisplay(iso);
    displayEl.style.color = '#fff';
  }

  _closeCalPopup();
}

function _initCalHeaderControls() {
  const hMonth = document.getElementById('cal-header-month');
  const hYear = document.getElementById('cal-header-year');

  if (hMonth && hMonth.options.length === 0) {
    THAI_MONTH_NAMES.forEach((name, i) => {
      const opt = document.createElement('option');
      opt.value = i;
      opt.textContent = name;
      hMonth.appendChild(opt);
    });
    hMonth.onchange = () => { _calState.month = parseInt(hMonth.value, 10); _renderCalDays(); };
  }

  if (hYear && hYear.options.length === 0) {
    for (let y = 2560; y <= 2585; y++) {
      const opt = document.createElement('option');
      opt.value = y - 543;
      opt.textContent = `${y} (${y - 543})`;
      hYear.appendChild(opt);
    }
    hYear.onchange = () => { _calState.yearAD = parseInt(hYear.value, 10); _renderCalDays(); };
  }

  const prevBtn = document.getElementById('cal-prev-month');
  const nextBtn = document.getElementById('cal-next-month');
  if (prevBtn) prevBtn.onclick = () => {
    _calState.month--;
    if (_calState.month < 0) { _calState.month = 11; _calState.yearAD--; }
    _renderCalDays();
  };
  if (nextBtn) nextBtn.onclick = () => {
    _calState.month++;
    if (_calState.month > 11) { _calState.month = 0; _calState.yearAD++; }
    _renderCalDays();
  };

  const todayBtn = document.getElementById('cal-today-btn');
  if (todayBtn) todayBtn.onclick = () => {
    const t = new Date();
    _calState.yearAD = t.getFullYear();
    _calState.month = t.getMonth();
    _calSelectDay(t.getDate());
  };

  const clearBtn = document.getElementById('cal-clear-btn');
  if (clearBtn) clearBtn.onclick = () => {
    const { prefix } = _calState;
    const hiddenEl = document.getElementById(_calHiddenId(prefix));
    if (hiddenEl) hiddenEl.value = '';
    const displayEl = document.getElementById(_calDisplayId(prefix));
    if (displayEl) { displayEl.textContent = 'เลือกวันที่...'; displayEl.style.color = '#aaa'; }
    _closeCalPopup();
  };
}

function _closeCalPopup() {
  const popup = document.getElementById('thai-cal-popup');
  if (popup) popup.style.display = 'none';
  _calState.prefix = null;
}

// Position popup relative to trigger button
window.openThaiCalendar = (prefix) => {
  const popup = document.getElementById('thai-cal-popup');
  const btn = document.getElementById(_calBtnId(prefix));
  if (!popup || !btn) return;

  _initCalHeaderControls();
  _calState.prefix = prefix;

  // Start at existing selected date, or today
  const hiddenEl = document.getElementById(_calHiddenId(prefix));
  const iso = hiddenEl ? hiddenEl.value : '';
  if (iso) {
    const p = iso.split('-');
    _calState.yearAD = parseInt(p[0], 10);
    _calState.month = parseInt(p[1], 10) - 1;
  } else {
    const t = new Date();
    _calState.yearAD = t.getFullYear();
    _calState.month = t.getMonth();
  }

  _renderCalDays();
  popup.style.display = 'block';

  // Position: below the button, or above if too far down
  const rect = btn.getBoundingClientRect();
  const popupH = 320;
  const spaceBelow = window.innerHeight - rect.bottom;
  const top = spaceBelow > popupH ? rect.bottom + 4 : rect.top - popupH - 4;
  let left = rect.left;
  if (left + 280 > window.innerWidth) left = window.innerWidth - 288;
  popup.style.top = `${top}px`;
  popup.style.left = `${Math.max(8, left)}px`;
};

// Close popup when clicking outside
document.addEventListener('click', (e) => {
  const popup = document.getElementById('thai-cal-popup');
  if (!popup || popup.style.display === 'none') return;
  if (!popup.contains(e.target) && !e.target.closest('[id^="cal-btn-"]')) {
    _closeCalPopup();
  }
}, true);

// Auto-detect Thai date from free text → ISO string (used by ingest modals if needed)
function autoDetectThaiDate(text) {
  if (!text) return null;
  text = text.trim();

  for (const [fullName, mm] of Object.entries(THAI_MONTHS_FULL)) {
    const re = new RegExp(`(\\d{1,2})\\s*${fullName}\\s*(\\d{2,4})`);
    const m = text.match(re);
    if (m) {
      const day = String(parseInt(m[1], 10)).padStart(2, '0');
      let year = parseInt(m[2], 10);
      if (year < 100) year += 2500;
      if (year > 2500) year -= 543;
      return `${year}-${mm}-${day}`;
    }
  }
  for (const [shortName, mm] of Object.entries(THAI_MONTHS_SHORT)) {
    const escaped = shortName.replace(/\./g, '\\.');
    const re = new RegExp(`(\\d{1,2})\\s*${escaped}\\s*(\\d{2,4})`);
    const m = text.match(re);
    if (m) {
      const day = String(parseInt(m[1], 10)).padStart(2, '0');
      let year = parseInt(m[2], 10);
      if (year < 100) year += 2500;
      if (year > 2500) year -= 543;
      return `${year}-${mm}-${day}`;
    }
  }
  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoMatch) return text;
  const slashMatch = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (slashMatch) {
    const dd = String(parseInt(slashMatch[1], 10)).padStart(2, '0');
    const mm2 = String(parseInt(slashMatch[2], 10)).padStart(2, '0');
    let yyyy = parseInt(slashMatch[3], 10);
    if (yyyy > 2500) yyyy -= 543;
    return `${yyyy}-${mm2}-${dd}`;
  }
  return null;
}

// Load existing ISO value into calendar button display (for openEditModal)
function loadIsoIntoThaiPicker(prefix, isoValue) {
  const hiddenEl = document.getElementById(_calHiddenId(prefix));
  if (hiddenEl) hiddenEl.value = isoValue || '';
  const displayEl = document.getElementById(_calDisplayId(prefix));
  if (displayEl) {
    if (isoValue) {
      displayEl.textContent = _isoToThaiDisplay(isoValue);
      displayEl.style.color = '#fff';
    } else {
      displayEl.textContent = 'เลือกวันที่...';
      displayEl.style.color = '#aaa';
    }
  }
}

