async function syncAdminSettingsFromCloud() {
  try {
    const authSnap = await getDoc(doc(db, 'admin_settings', 'auth'));
    if (authSnap.exists()) {
      const data = authSnap.data();
      if (data && data.admin_pin) {
        cloudAdminPin = String(data.admin_pin).trim();
        localStorage.setItem('dept_doc_vault_admin_pin', cloudAdminPin);
      }
    }
  } catch (err) {
    console.warn('Cloud PIN sync notice:', err.message);
  }

  try {
    const catOrderSnap = await getDoc(doc(db, 'admin_settings', 'categories_order'));
    if (catOrderSnap.exists()) {
      const data = catOrderSnap.data();
      if (data && Array.isArray(data.order)) {
        localStorage.setItem('dept_custom_category_order', JSON.stringify(data.order));
        renderMainCategorySwitcher();
        renderCategoryTabsManager();
      }
    }
  } catch (err) {
    console.warn('Cloud category order sync notice:', err.message);
  }
}

