function updateAdminUI() {
  const adminOnlyElements = document.querySelectorAll('.admin-only-btn');
  const btnOpenAdminLoginTop = document.getElementById('btn-open-admin-login-top');
  const btnAdminStatusTop = document.getElementById('btn-admin-status-top');
  const sidebarAppVersion = document.getElementById('sidebar-app-version');

  if (sidebarAppVersion) sidebarAppVersion.innerText = APP_VERSION;
  
  if (state.isAdmin) {
    adminOnlyElements.forEach(el => el.style.display = '');
    if (adminStatusTag) adminStatusTag.style.display = 'none';
    if (btnAdminStatusTop) {
      btnAdminStatusTop.style.display = 'inline-flex';
      btnAdminStatusTop.innerHTML = `<i data-lucide="shield-check" style="width: 13px; height: 13px; color: var(--apple-mint);"></i> <span>👑 ADMIN</span>`;
      lucide.createIcons();
    }
    if (btnOpenAdminLoginTop) btnOpenAdminLoginTop.style.display = 'none';
    if (appLogoBtn) {
      appLogoBtn.title = `Service Hub ${APP_VERSION} (โหมดผู้ดูแล - คลิกเพื่อออกจากระบบ)`;
    }
  } else {
    adminOnlyElements.forEach(el => el.style.display = 'none');
    if (adminStatusTag) adminStatusTag.style.display = 'none';
    if (btnAdminStatusTop) btnAdminStatusTop.style.display = 'none';
    if (btnOpenAdminLoginTop) btnOpenAdminLoginTop.style.display = 'inline-flex';
    if (appLogoBtn) {
      appLogoBtn.title = `Service Hub ${APP_VERSION}`;
    }
  }

  renderMainCategorySwitcher();
  renderCategoryTabsManager();
  renderServicesView();
  renderSidebarList();
}

