// ==========================================================================
// 📅 Department Calendar & Operations Schedule Engine
// ==========================================================================
async function loadCalendarEvents() {
  try {
    const list = [...DEFAULT_CALENDAR_EVENTS];
    const snap = await getDocs(collection(db, 'calendar_events'));
    snap.forEach(d => {
      list.push({ id: d.id, ...d.data() });
    });

    state.calendarEvents = list;
  } catch (err) {
    console.warn('Load calendar events notice:', err.message);
    state.calendarEvents = [...DEFAULT_CALENDAR_EVENTS];
  }
}

function getCombinedEvents() {
  const allEvents = [...state.calendarEvents];

  // Pull promotion dates from services
  state.services.forEach(s => {
    if (s.category_type === 'promotions') {
      if (s.end_date && !allEvents.some(e => e.serviceId === s.id && e.date === s.end_date)) {
        allEvents.push({
          id: `promo-end-${s.id}`,
          serviceId: s.id,
          title: `🟡 หมดเขต: ${s.name}`,
          type: 'promo',
          date: s.end_date,
          time: '23:59 น.',
          detail: s.summary || s.description || 'สิ้นสุดระยะเวลาโปรโมชั่น'
        });
      }
      if (s.start_date && !allEvents.some(e => e.serviceId === s.id && e.date === s.start_date)) {
        allEvents.push({
          id: `promo-start-${s.id}`,
          serviceId: s.id,
          title: `🟡 เริ่มโปร: ${s.name}`,
          type: 'promo',
          date: s.start_date,
          time: '08:30 น.',
          detail: s.summary || s.description || 'เริ่มเปิดใช้งานโปรโมชั่น'
        });
      }
    }
  });

  return allEvents.filter(e => e.type !== 'cutoff');
}

function renderDepartmentCalendar() {
  const monthNames = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];
  const thaiYear = state.calViewYear + 543;
  calCurrentMonthLabel.innerText = `${monthNames[state.calViewMonth]} ${thaiYear}`;

  const firstDayIndex = new Date(state.calViewYear, state.calViewMonth, 1).getDay();
  const lastDayCurrentMonth = new Date(state.calViewYear, state.calViewMonth + 1, 0).getDate();
  const lastDayPrevMonth = new Date(state.calViewYear, state.calViewMonth, 0).getDate();

  const allEvents = getCombinedEvents();
  let daysHtml = '';

  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

  for (let x = firstDayIndex; x > 0; x--) {
    const dayNum = lastDayPrevMonth - x + 1;
    daysHtml += `<div class="cal-day-cell other-month"><span class="day-num">${dayNum}</span></div>`;
  }

  for (let i = 1; i <= lastDayCurrentMonth; i++) {
    const currentMonthStr = String(state.calViewMonth + 1).padStart(2, '0');
    const currentDayStr = String(i).padStart(2, '0');
    const dateStr = `${state.calViewYear}-${currentMonthStr}-${currentDayStr}`;

    const isToday = dateStr === todayStr ? 'today' : '';
    const isSelected = dateStr === state.calSelectedDate ? 'selected' : '';

    const dayEvents = allEvents.filter(e => e.date === dateStr);
    const dotsHtml = dayEvents.slice(0, 3).map(e => `<span class="cal-dot ${e.type || 'dept'}"></span>`).join('');

    daysHtml += `
      <div class="cal-day-cell ${isToday} ${isSelected}" data-date="${dateStr}" onclick="window.selectCalendarDate('${dateStr}')">
        <span class="day-num">${i}</span>
        <div class="cal-day-dots">${dotsHtml}</div>
      </div>
    `;
  }

  const totalRendered = firstDayIndex + lastDayCurrentMonth;
  const remainingCells = (totalRendered <= 35 ? 35 : 42) - totalRendered;
  for (let j = 1; j <= remainingCells; j++) {
    daysHtml += `<div class="cal-day-cell other-month"><span class="day-num">${j}</span></div>`;
  }

  calendarDaysGrid.innerHTML = daysHtml;
  renderAgendaEvents(state.calSelectedDate);
}

window.selectCalendarDate = (dateStr) => {
  state.calSelectedDate = dateStr;
  document.querySelectorAll('.cal-day-cell').forEach(c => {
    c.classList.toggle('selected', c.dataset.date === dateStr);
  });
  renderAgendaEvents(dateStr);
};

function getCustomCalendarTypes() {
  try {
    return JSON.parse(localStorage.getItem('dept_custom_cal_types')) || [];
  } catch (e) {
    return [];
  }
}

function saveCustomCalendarType(typeName) {
  if (!typeName) return;
  const list = getCustomCalendarTypes();
  if (!list.includes(typeName)) {
    list.push(typeName);
    try {
      localStorage.setItem('dept_custom_cal_types', JSON.stringify(list));
    } catch (e) {}
  }
}

function populateCalendarEventTypeDropdown(selectedValue = 'leave') {
  if (!eventType) return;
  const customTypes = getCustomCalendarTypes();
  let customOptionsHtml = '';
  if (customTypes.length > 0) {
    customOptionsHtml = `<optgroup label="🏷️ ประเภทกำหนดการที่ท่านสร้างเอง">
      ${customTypes.map(t => `<option value="custom_${t}" ${selectedValue === `custom_${t}` ? 'selected' : ''}>📌 ${t}</option>`).join('')}
    </optgroup>`;
  }

  eventType.innerHTML = `
    <option value="leave" ${selectedValue === 'leave' ? 'selected' : ''}>🏖️ ลาพักร้อน / ลากิจ / ลาป่วย</option>
    <option value="duty" ${selectedValue === 'duty' ? 'selected' : ''}>🚗 ไปปฏิบัติหน้าที่ / อบรม / เวรพิเศษ</option>
    <option value="holiday" ${selectedValue === 'holiday' ? 'selected' : ''}>🟡 วันหยุดนักขัตฤกษ์ (เปิดบริการพิเศษ 08:00 - 17:00 น.)</option>
    <option value="closed" ${selectedValue === 'closed' ? 'selected' : ''}>🔴 วันสิ้นปี / ปิดทำการพิเศษ</option>
    <option value="dept" ${selectedValue === 'dept' ? 'selected' : ''}>🟢 กิจกรรมแผนก / ประชุม / สต็อก</option>
    <option value="promo" ${selectedValue === 'promo' ? 'selected' : ''}>🟠 โปรโมชั่น & ส่วนลด</option>
    ${customOptionsHtml}
    <option value="CUSTOM_NEW">✨ [+ เพิ่มประเภท/หัวข้อกำหนดการใหม่เอง...]</option>
  `;

  const customBox = document.getElementById('custom-event-type-box');
  const customNameInput = document.getElementById('custom-event-type-name');
  if (customBox) customBox.style.display = selectedValue === 'CUSTOM_NEW' ? 'block' : 'none';

  eventType.onchange = () => {
    if (eventType.value === 'CUSTOM_NEW') {
      if (customBox) customBox.style.display = 'block';
      if (customNameInput) {
        customNameInput.focus();
        customNameInput.required = true;
      }
    } else {
      if (customBox) customBox.style.display = 'none';
      if (customNameInput) customNameInput.required = false;
    }
  };
}

function renderAgendaEvents(dateStr) {
  agendaSelectedDateTitle.innerText = formatFullThaiDate(dateStr);
  const allEvents = getCombinedEvents();
  const dayEvents = allEvents.filter(e => e.date === dateStr);

  if (dayEvents.length === 0) {
    agendaSubtitle.innerText = 'ไม่มีกำหนดการพิเศษในวันนี้';
    agendaEventsList.innerHTML = `
      <div style="text-align: center; padding: 32px 0; color: var(--text-secondary);">
        <i data-lucide="calendar-check-2" style="width: 32px; height: 32px; color: var(--apple-blue); margin-bottom: 6px;"></i>
        <p style="font-size: 0.84rem;">ไม่มีนัดหมายหรือวันหยุดพิเศษในวันนี้</p>
        <p style="font-size: 0.74rem; color: var(--text-tertiary); margin-top: 2px;">เปิดทำการและให้บริการตามเวลาปกติ</p>
      </div>
    `;
    lucide.createIcons();
    return;
  }

  agendaSubtitle.innerText = `มี ${dayEvents.length} รายการกำหนดการ`;

  agendaEventsList.innerHTML = dayEvents.map(e => {
    let typeBadge = '🟢 กิจกรรมแผนก/สต็อก';
    let cardClass = e.type || 'dept';

    if (e.type === 'leave') {
      typeBadge = '🏖️ ลาพักร้อน/ลากิจ';
      cardClass = 'leave';
    } else if (e.type === 'duty') {
      typeBadge = '🚗 ไปปฏิบัติหน้าที่/อบรม';
      cardClass = 'duty';
    } else if (e.type === 'holiday') {
      typeBadge = '🟡 วันหยุดนักขัตฤกษ์ (เปิดพิเศษ 08:00 - 17:00 น.)';
      cardClass = 'holiday';
    } else if (e.type === 'closed') {
      typeBadge = '🔴 วันหยุดสิ้นปี (ปิดทำการประจำปี)';
      cardClass = 'closed';
    } else if (e.type === 'promo') {
      typeBadge = '🟠 โปรโมชั่น & ส่วนลด';
      cardClass = 'promo';
    } else if (e.type === 'cutoff') {
      typeBadge = '🔵 รอบรถตัดตอน';
      cardClass = 'cutoff';
    } else if (e.type && e.type.startsWith('custom_')) {
      const customName = e.customTypeName || e.type.replace('custom_', '');
      typeBadge = `📌 ${customName}`;
      cardClass = 'custom';
    }

    return `
      <div class="agenda-event-card ${cardClass}">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 8px;">
          <div>
            <span style="font-size: 0.7rem; font-weight: 700; color: var(--text-secondary); text-transform: uppercase;">
              ${typeBadge} ${e.time ? `• ⏰ ${e.time}` : ''}
            </span>
            <h5 style="font-size: 0.9rem; font-weight: 700; color: #fff; margin: 2px 0 4px;">${e.title}</h5>
          </div>
          ${state.isAdmin && !e.isPreset ? `
            <div style="display: flex; gap: 4px;">
              <button class="btn-icon" onclick="window.editCalendarEvent('${e.id}')" title="แก้ไข">
                <i data-lucide="edit-3" style="width: 12px; height: 12px;"></i>
              </button>
              <button class="btn-icon danger" onclick="window.deleteCalendarEvent('${e.id}')" title="ลบ">
                <i data-lucide="trash-2" style="width: 12px; height: 12px;"></i>
              </button>
            </div>
          ` : ''}
        </div>
        ${e.detail ? `<p style="font-size: 0.8rem; color: var(--text-secondary); line-height: 1.4; margin: 0;">${e.detail}</p>` : ''}
      </div>
    `;
  }).join('');

  lucide.createIcons();
}

window.editCalendarEvent = (id) => {
  const ev = state.calendarEvents.find(e => e.id === id);
  if (!ev) return;
  eventDocId.value = ev.id;
  eventTitle.value = ev.title || '';
  populateCalendarEventTypeDropdown(ev.type || 'leave');
  eventDate.value = ev.date || state.calSelectedDate;
  eventTime.value = ev.time || '';
  eventDetail.value = ev.detail || '';
  calendarEventModalTitle.innerText = 'แก้ไขกำหนดการแผนก';
  calendarEventModal.classList.add('active');
  lucide.createIcons();
};

window.deleteCalendarEvent = async (id) => {
  if (!state.isAdmin) return;
  if (!confirm('ยืนยัน: ต้องการลบกำหนดการนี้ใช่หรือไม่?')) return;
  try {
    await deleteDoc(doc(db, 'calendar_events', id));
    showToast('ลบกำหนดการเรียบร้อยแล้ว', 'success');
    await loadCalendarEvents();
    renderDepartmentCalendar();
  } catch (err) {
    showToast('ลบไม่สำเร็จ: ' + err.message, 'danger');
  }
};

calendarEventForm.onsubmit = async (e) => {
  e.preventDefault();
  if (!state.isAdmin) return;

  let selectedType = eventType.value;
  let customTypeName = '';
  if (selectedType === 'CUSTOM_NEW') {
    const rawName = document.getElementById('custom-event-type-name')?.value.trim();
    if (rawName) {
      saveCustomCalendarType(rawName);
      selectedType = `custom_${rawName}`;
      customTypeName = rawName;
    } else {
      selectedType = 'dept';
    }
  } else if (selectedType.startsWith('custom_')) {
    customTypeName = selectedType.replace('custom_', '');
  }

  const id = eventDocId.value;
  const payload = {
    title: eventTitle.value.trim(),
    type: selectedType,
    customTypeName: customTypeName,
    date: eventDate.value,
    time: eventTime.value.trim(),
    detail: eventDetail.value.trim(),
    updated_at: serverTimestamp()
  };

  const btnSubmit = document.getElementById('btn-submit-event');
  btnSubmit.disabled = true;
  btnSubmit.innerText = 'กำลังบันทึก...';

  try {
    if (id) {
      await updateDoc(doc(db, 'calendar_events', id), payload);
      showToast('แก้ไขกำหนดการเรียบร้อยแล้ว', 'success');
    } else {
      payload.created_at = serverTimestamp();
      await addDoc(collection(db, 'calendar_events'), payload);
      showToast('เพิ่มกำหนดการใหม่เรียบร้อยแล้ว', 'success');
    }

    state.calSelectedDate = payload.date;
    calendarEventModal.classList.remove('active');
    await loadCalendarEvents();
    renderDepartmentCalendar();
  } catch (err) {
    showToast('บันทึกไม่สำเร็จ: ' + err.message, 'danger');
  } finally {
    btnSubmit.disabled = false;
    btnSubmit.innerText = 'บันทึกกำหนดการ';
  }
};

// ==========================================================================
// 🪄 Secret 5-Arrow / 5-Click Auto-Fill Trick (ทริคกด -> 5 ครั้ง)
// ==========================================================================
let arrowRightPressCount = 0;
let lastArrowPressTime = 0;

function triggerSecretAutofill() {
  if (adminEmailInput) adminEmailInput.value = REGISTERED_ADMIN_EMAIL;
  if (resetEmailInput) resetEmailInput.value = REGISTERED_ADMIN_EMAIL;

  if (adminPinModal.classList.contains('active')) {
    switchLoginTab('email');
    if (adminPasswordInput) adminPasswordInput.focus();
  }

  showToast('✨ ป้อนอีเมลผู้ดูแลให้อัตโนมัติแล้ว', 'success');
}

function setupSecretArrowTrick() {
  window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.code === 'ArrowRight') {
      const now = Date.now();
      if (now - lastArrowPressTime > 2500) {
        arrowRightPressCount = 0;
      }
      lastArrowPressTime = now;
      arrowRightPressCount++;

      if (arrowRightPressCount >= 5) {
        arrowRightPressCount = 0;
        triggerSecretAutofill();
      }
    }
  });

  if (adminShieldIcon) {
    let shieldClicks = 0;
    let lastShieldClick = 0;
    adminShieldIcon.onclick = () => {
      const now = Date.now();
      if (now - lastShieldClick > 2500) shieldClicks = 0;
      lastShieldClick = now;
      shieldClicks++;

      if (shieldClicks >= 5) {
        shieldClicks = 0;
        triggerSecretAutofill();
      } else {
        switchLoginTab(adminPinForm.style.display === 'none' ? 'pin' : 'email');
      }
    };
  }
}

function switchLoginTab(mode) {
  if (mode === 'email') {
    tabLoginEmail.classList.add('active');
    tabLoginEmail.style.background = 'var(--apple-blue)';
    tabLoginEmail.style.color = '#fff';

    tabLoginPin.classList.remove('active');
    tabLoginPin.style.background = 'transparent';
    tabLoginPin.style.color = 'var(--text-secondary)';

    adminPinForm.style.display = 'none';
    adminEmailForm.style.display = 'block';
    if (adminEmailError) adminEmailError.style.display = 'none';
    setTimeout(() => {
      if (!adminEmailInput.value) adminEmailInput.focus();
      else adminPasswordInput.focus();
    }, 100);
  } else {
    tabLoginPin.classList.add('active');
    tabLoginPin.style.background = 'var(--apple-blue)';
    tabLoginPin.style.color = '#fff';

    tabLoginEmail.classList.remove('active');
    tabLoginEmail.style.background = 'transparent';
    tabLoginEmail.style.color = 'var(--text-secondary)';

    adminEmailForm.style.display = 'none';
    adminPinForm.style.display = 'block';
    if (adminPinError) adminPinError.style.display = 'none';
    setTimeout(() => adminPinInput && adminPinInput.focus(), 100);
  }
}

function setupCustomizerPickers() {
  document.querySelectorAll('#color-palette-picker .color-swatch').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#color-palette-picker .color-swatch').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const chosenColor = btn.dataset.color;
      document.getElementById('form-selected-color').value = chosenColor;
      if (formHeaderIconBox) formHeaderIconBox.style.background = chosenColor;
    };
  });

  document.querySelectorAll('#icon-picker-grid .icon-choice-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#icon-picker-grid .icon-choice-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const chosenIcon = btn.dataset.icon;
      document.getElementById('form-selected-icon').value = chosenIcon;
      if (formHeaderIcon) {
        formHeaderIcon.setAttribute('data-lucide', chosenIcon);
        lucide.createIcons();
      }
    };
  });
}

function setSelectedCustomizerVisuals(color = '#0071e3', icon = 'package') {
  document.getElementById('form-selected-color').value = color;
  document.getElementById('form-selected-icon').value = icon;

  document.querySelectorAll('#color-palette-picker .color-swatch').forEach(b => {
    b.classList.toggle('active', b.dataset.color.toLowerCase() === color.toLowerCase());
  });

  document.querySelectorAll('#icon-picker-grid .icon-choice-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.icon.toLowerCase() === icon.toLowerCase());
  });

  if (formHeaderIconBox) formHeaderIconBox.style.background = color;
  if (formHeaderIcon) {
    formHeaderIcon.setAttribute('data-lucide', icon);
    lucide.createIcons();
  }
}

