function showToast(message, type = 'info') {
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  let icon = 'info';
  if (type === 'success') icon = 'check-circle';
  if (type === 'danger') icon = 'alert-circle';
  
  toast.innerHTML = `<i data-lucide="${icon}"></i><span>${message}</span>`;
  toastContainer.appendChild(toast);
  lucide.createIcons();
  
  setTimeout(() => {
    toast.style.animation = 'toastSlide 0.25s reverse forwards';
    setTimeout(() => toast.remove(), 250);
  }, 3500);
}

function debounce(func, wait) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
}

window.shareDocumentLink = (title, url) => {
  const text = `📄 ข้อมูลบริการ/โปรโมชั่น: ${title}\n🔗 ลิงก์: ${url}`;
  navigator.clipboard.writeText(text).catch(() => {});
  const lineUrl = `https://line.me/R/msg/text/?${encodeURIComponent(text)}`;
  window.open(lineUrl, '_blank', 'noopener,noreferrer');
  showToast('เปิด LINE ส่งข้อมูลเรียบร้อยแล้ว', 'success');
};

window.copyToClipboard = (text, label = 'คัดลอกเรียบร้อยแล้ว') => {
  navigator.clipboard.writeText(text).then(() => {
    showToast(label, 'success');
  }).catch(() => {
    showToast('ไม่สามารถคัดลอกได้', 'danger');
  });
};

function getEmbedUrl(url) {
  if (!url) return '';
  if (url.includes('drive.google.com/file/d/')) {
    const match = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (match && match[1]) {
      return `https://drive.google.com/file/d/${match[1]}/preview`;
    }
  }
  return url;
}

// ==========================================================================
// Service Normalization & Lego Blocks Engine
// ==========================================================================
function normalizeService(raw, id, collectionName = 'categories') {
  let catType = raw.category_type || 'domestic';
  const nameLower = (raw.name || raw.title || '').toLowerCase();
  const descLower = (raw.description || '').toLowerCase();

  if (raw.category_type) {
    catType = raw.category_type;
  } else if (nameLower.includes('โปรโมชั่น') || nameLower.includes('ส่วนลด') || nameLower.includes('promo') || descLower.includes('โปรโมชั่น')) {
    catType = 'promotions';
  } else if (nameLower.includes('ประกาศ') || nameLower.includes('ข่าว') || nameLower.includes('ปรับอัตรา') || nameLower.includes('นิเทศ')) {
    catType = 'news';
  } else if (nameLower.includes('fuze') || nameLower.includes('อุณหภูมิ') || descLower.includes('fuze')) {
    catType = 'coldchain';
  } else if (
    nameLower.includes('world') || nameLower.includes('inter') || 
    nameLower.includes('courier') || nameLower.includes('epacket') || 
    nameLower.includes('usa') || nameLower.includes('สหรัฐ') ||
    nameLower.includes('ต่างประเทศ') || nameLower.includes('ระหว่างประเทศ') ||
    descLower.includes('ระหว่างประเทศ')
  ) {
    catType = 'international';
  } else {
    catType = 'domestic';
  }

  const preset = THP_SERVICE_PRESETS[id] || {};

  let specs = raw.specs;
  if (!specs || (!specs.weight && !specs.size && !specs.sla && !specs.rate)) {
    specs = {
      weight: raw.spec_weight || preset.specs?.weight || '',
      size: raw.spec_size || preset.specs?.size || '',
      sla: raw.spec_sla || preset.specs?.sla || '',
      rate: raw.spec_rate || preset.specs?.rate || ''
    };
  }

  const reqDocs = (raw.required_docs && raw.required_docs.length > 0) ? 
    raw.required_docs : 
    (preset.required_docs || []);

  const sopSteps = (raw.sop_steps && raw.sop_steps.length > 0) ? 
    raw.sop_steps : 
    (preset.sop_steps || []);

  let summary = raw.summary || preset.summary || '';
  if (summary === 'เตรียมเพิ่มรายละเอียด เอกสาร และลิงก์ที่เกี่ยวข้อง' && preset.summary) {
    summary = preset.summary;
  }

  const links = raw.links || (raw.file_url ? [{ title: raw.title || 'เอกสารแนบ', url: raw.file_url }] : []);
  const description = raw.description || '';

  const startDate = raw.start_date || '';
  const endDate = raw.end_date || '';

  let defaultColor = '#0071e3';
  let defaultIcon = 'package';
  if (catType === 'coldchain') { defaultColor = '#64d2ff'; defaultIcon = 'snowflake'; }
  else if (catType === 'international') { defaultColor = '#ff9500'; defaultIcon = 'globe'; }
  else if (catType === 'promotions') { defaultColor = '#ffd60a'; defaultIcon = 'gift'; }
  else if (catType === 'news') { defaultColor = '#ff9f0a'; defaultIcon = 'megaphone'; }

  const color = raw.color || preset.color || defaultColor;
  const icon = raw.icon || preset.icon || defaultIcon;
  const activeStatus = raw.active !== false;

  let blocks = raw.blocks;
  if (!blocks || !Array.isArray(blocks) || blocks.length === 0) {
    blocks = [];

    if (specs.weight || specs.size || specs.sla || specs.rate) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'specs_table',
        title: 'ตารางข้อมูลบริการ (Service Specs)',
        data: specs
      });
    }

    const customTable = preset.custom_table || raw.custom_table;
    if (customTable) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'custom_table',
        title: customTable.title || 'ตารางอัตราค่าบริการเพิ่มเติม',
        data: customTable
      });
    }

    if (reqDocs.length > 0) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'checklist',
        title: 'เอกสาร / สิ่งที่ต้องมีในการรับฝาก',
        data: reqDocs
      });
    }

    if (sopSteps.length > 0) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'sop_steps',
        title: 'วิธีปฏิบัติงาน & ขั้นตอนการรับฝาก (SOP)',
        data: sopSteps
      });
    }

    if (links.length > 0) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'pdf_embed',
        title: 'บันทึกสั่งการ & เอกสารแนบ',
        data: links
      });
    }

    if (description) {
      blocks.push({
        id: 'block_' + Math.random().toString(36).substr(2, 9),
        type: 'text_block',
        title: 'รายละเอียด & ข้อกำหนดเพิ่มเติม',
        data: { text: description }
      });
    }
  }

  let serviceGroup = raw.service_group || preset.service_group || '';
  if (!serviceGroup) {
    if (id.includes('mail-1') || nameLower.includes('จดหมาย')) serviceGroup = 'letter';
    else if (id.includes('printed') || nameLower.includes('สิ่งตีพิมพ์')) serviceGroup = 'printed_matter';
    else if (id.includes('parcel') || nameLower.includes('พัสดุ')) serviceGroup = 'parcel';
    else if (id.includes('mail-2') || nameLower.includes('ลงทะเบียน')) serviceGroup = 'registered';
    else if (id.includes('eco-post') || nameLower.includes('eco-post')) serviceGroup = 'ecopost';
    else if (id.includes('epacket') || nameLower.includes('epacket')) serviceGroup = 'epacket';
    else if (id.includes('mail-3') || id.includes('ems-world') || nameLower.includes('ems')) serviceGroup = 'ems';
    else if (id.includes('courier') || nameLower.includes('courier')) serviceGroup = 'courierpost';
    else if (id.includes('admail') || nameLower.includes('advertis')) serviceGroup = 'admail';
    else if (id.includes('travel-lite') || nameLower.includes('travel')) serviceGroup = 'travellite';
  }

  return {
    id: id,
    collectionName: collectionName,
    name: raw.name || raw.title || 'บริการไปรษณีย์',
    service_group: serviceGroup,
    category_type: catType,
    start_date: startDate,
    end_date: endDate,
    summary: summary,
    description: description,
    icon: icon,
    color: color,
    active: activeStatus,
    order: parseInt(raw.order || 99, 10),
    specs: specs,
    blocks: blocks,
    updated_at: raw.updated_at || raw.upload_date || ''
  };
}

// ==========================================================================
// Data Fetching & Integration
// ==========================================================================
async function loadAllServices() {
  if (servicesGrid) {
    servicesGrid.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 36px 0; color: var(--text-secondary);">
        <p>กำลังโหลดข้อมูลบริการและโปรโมชั่น...</p>
      </div>
    `;
  }

  let list = [];

  // 1. Try reading from Firestore 'categories' collection safely
  try {
    const catSnapshot = await getDocs(collection(db, 'categories'));
    if (catSnapshot && !catSnapshot.empty) {
      catSnapshot.forEach(docSnap => {
        const data = docSnap.data();
        if (data && data.name && !data.template_marker) {
          list.push(normalizeService(data, docSnap.id, 'categories'));
        }
      });
    }
  } catch (err) {
    console.warn('Firestore categories read notice:', err.message);
  }

  // 2. Try reading from Firestore 'documents' collection safely
  try {
    const docSnapshot = await getDocs(collection(db, 'documents'));
    if (docSnapshot && !docSnapshot.empty) {
      docSnapshot.forEach(docSnap => {
        const data = docSnap.data();
        if (data && data.title && !list.some(s => s.id === docSnap.id)) {
          list.push(normalizeService(data, docSnap.id, 'documents'));
        }
      });
    }
  } catch (err) {
    console.warn('Firestore documents read notice:', err.message);
  }

  // 3. Guarantee all Standard & Extended Domestic Services exist and have official PDFs
  DEFAULT_DOMESTIC_SERVICES.forEach(dom => {
    const match = list.find(s => s.id === dom.id);
    if (!match) {
      list.push(dom);
    } else {
      if (dom.blocks) {
        match.blocks = dom.blocks;
      }
      if (dom.specs) {
        match.specs = dom.specs;
      }
      match.color = '#30d158';
      match.name = dom.name;
      match.service_group = dom.service_group || match.service_group;
    }
  });

  if (!list.some(s => s.id === 'domestic-boxes-packaging' || (s.name || '').includes('กล่อง ซอง'))) {
    list.push(DEFAULT_PACKAGING_SERVICE);
  }
  
  // Check if user already has an authentic EMS Jumbo card in database
  const existingJumboIndex = list.findIndex(s => {
    const n = (s.name || '').toLowerCase();
    return (n.includes('jumbo') || n.includes('จัมโบ้') || n.includes('logispost')) && s.id !== 'domestic-ems-jumbo';
  });

  if (existingJumboIndex === -1) {
    if (!list.some(s => s.id === 'domestic-ems-jumbo')) {
      list.push(DEFAULT_EMS_JUMBO_SERVICE);
    }
  } else {
    // User has existing authentic card -> remove duplicate fallback
    const duplicateFallbackIdx = list.findIndex(s => s.id === 'domestic-ems-jumbo');
    if (duplicateFallbackIdx !== -1) {
      list.splice(duplicateFallbackIdx, 1);
    }
  }

  // 3. Guarantee all Standard International Pillar Services exist
  DEFAULT_INTL_SERVICES.forEach(intl => {
    const match = list.find(s => s.id === intl.id);
    if (!match) {
      list.push(intl);
    } else {
      if (intl.blocks && (!match.blocks || match.blocks.length < intl.blocks.length)) {
        match.blocks = intl.blocks;
      }
      if (intl.specs) {
        match.specs = intl.specs;
      }
      match.name = intl.name;
      match.color = intl.color;
      match.service_group = intl.service_group || match.service_group;
    }
  });

  // Clean up any stray or redundant international cards from Firestore
  list = list.filter(s => {
    if (s.category_type === 'international') {
      const isPillar = DEFAULT_INTL_SERVICES.some(p => p.id === s.id);
      if (!isPillar) {
        // If it's a news item like philippines or epacket-ddp-eu, redirect it to news or merge
        if ((s.name || '').includes('ฟิลิปปินส์') || (s.name || '').includes('ล่าช้า')) {
          s.category_type = 'news';
          return true;
        }
        if (s.id === 'intl-epacket-ddp-eu' || s.id === 'intl-usa-guide') {
          return false;
        }
      }
    }
    return true;
  });

  // Keep only the single unified master FUZE POST card
  list = list.filter(s => s.category_type !== 'coldchain' || s.id === 'fuze-post-master');
  const existingColdMaster = list.find(s => s.id === 'fuze-post-master');
  if (!existingColdMaster) {
    list.push(DEFAULT_COLDCHAIN_SERVICES[0]);
  } else {
    existingColdMaster.blocks = DEFAULT_COLDCHAIN_SERVICES[0].blocks;
    existingColdMaster.specs = DEFAULT_COLDCHAIN_SERVICES[0].specs;
    existingColdMaster.name = DEFAULT_COLDCHAIN_SERVICES[0].name;
    existingColdMaster.summary = DEFAULT_COLDCHAIN_SERVICES[0].summary;
    existingColdMaster.color = DEFAULT_COLDCHAIN_SERVICES[0].color;
  }

  const hasPromosInDb = list.some(s => s.category_type === 'promotions');
  if (!hasPromosInDb) {
    DEFAULT_PROMOTIONS.forEach(promo => list.push(promo));
  }

  const hasNewsInDb = list.some(s => s.category_type === 'news');
  if (!hasNewsInDb) {
    DEFAULT_NEWS.forEach(newsItem => list.push(newsItem));
  }

  // 4. Merge any locally saved memo additions or edits
  try {
    const cached = localStorage.getItem('dept_services_cache');
    if (cached) {
      const cachedList = JSON.parse(cached);
      if (Array.isArray(cachedList) && cachedList.length > 0) {
        cachedList.forEach(cItem => {
          const match = list.find(s => s.id === cItem.id);
          if (match) {
            if (cItem.blocks && cItem.blocks.length > (match.blocks || []).length && !match.isLocalFallback) {
              match.blocks = cItem.blocks;
            }
            if (cItem.version_history) {
              match.version_history = cItem.version_history;
            }
            if (cItem.summary && !match.isLocalFallback) match.summary = cItem.summary;
          } else {
            list.push(cItem);
          }
        });
      }
    }
  } catch (e) {}

  // Filter out any obsolete mockup data and raw OCR checklist dumps
  const isMockPromo = (id) => id === 'promo-weekend-ems' || id === 'promo-fuze-pickup' || id === 'promo-epacket-usa' || id === 'promo-post-family';
  list = list.filter(s => !isMockPromo(s.id));

  // Clean up any unnecessary raw OCR checklist dump blocks
  list.forEach(s => {
    if (Array.isArray(s.blocks)) {
      s.blocks = s.blocks.filter(b => {
        if (b.type === 'checklist' && (b.id?.startsWith('blk_pdf_ref_') || (b.title || '').includes('สาระสำคัญตามบันทึก'))) {
          const isOcrDump = Array.isArray(b.data) && b.data.some(d => typeof d === 'string' && (d.includes('กศศก') || d.includes('บนนทขอความ') || d.length > 250));
          if (isOcrDump) return false;
        }
        return true;
      });
    }
  });

  // Strictly enforce only the single unified master FUZE POST card
  list = list.filter(s => s.category_type !== 'coldchain' || s.id === 'fuze-post-master');
  if (!list.some(s => s.id === 'fuze-post-master')) {
    list.push(DEFAULT_COLDCHAIN_SERVICES[0]);
  } else {
    const m = list.find(s => s.id === 'fuze-post-master');
    m.blocks = DEFAULT_COLDCHAIN_SERVICES[0].blocks;
    m.specs = DEFAULT_COLDCHAIN_SERVICES[0].specs;
    m.name = DEFAULT_COLDCHAIN_SERVICES[0].name;
    m.summary = DEFAULT_COLDCHAIN_SERVICES[0].summary;
    m.color = DEFAULT_COLDCHAIN_SERVICES[0].color;
  }

  // Read deleted IDs blacklist from local storage
  let deletedIds = [];
  try {
    deletedIds = JSON.parse(localStorage.getItem('dept_deleted_service_ids') || '[]');
  } catch (e) {}

  if (deletedIds.length > 0) {
    list = list.filter(s => !deletedIds.includes(s.id));
  }

  list.sort((a, b) => (a.order - b.order) || a.name.localeCompare(b.name, 'th'));

  state.services = list;
  try {
    localStorage.setItem('dept_services_cache', JSON.stringify(state.services));
  } catch (e) {}
  updateNotificationCenter();
  renderSidebarList();
  renderServicesView();
}

// ==========================================================================
// 🖐️ Smooth Drag & Drop Reordering Engine (Mobile Touch & Desktop Mouse)
// ==========================================================================
let draggedCardId = null;
let touchDragEl = null;
let touchStartX = 0;
let touchStartY = 0;
let isTouchDragging = false;
let touchTimer = null;

function setupDragAndDropHandlers() {
  if (!state.isAdmin) return;

  const cards = document.querySelectorAll('.service-card.is-draggable');
  cards.forEach(card => {
    // Desktop Drag & Drop
    card.ondragstart = (e) => {
      draggedCardId = card.dataset.id;
      card.classList.add('is-dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', card.dataset.id);
    };

    card.ondragover = (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      if (card.dataset.id !== draggedCardId) {
        card.classList.add('drag-over');
      }
    };

    card.ondragleave = () => {
      card.classList.remove('drag-over');
    };

    card.ondrop = async (e) => {
      e.preventDefault();
      card.classList.remove('drag-over');
      const targetId = card.dataset.id;
      if (draggedCardId && targetId && draggedCardId !== targetId) {
        await swapServiceItems(draggedCardId, targetId);
      }
    };

    card.ondragend = () => {
      cards.forEach(c => {
        c.classList.remove('is-dragging');
        c.classList.remove('drag-over');
      });
      draggedCardId = null;
    };

    // Mobile Touch & Hold Drag
    card.ontouchstart = (e) => {
      const touch = e.touches[0];
      touchStartX = touch.clientX;
      touchStartY = touch.clientY;
      touchDragEl = card;
      draggedCardId = card.dataset.id;

      touchTimer = setTimeout(() => {
        isTouchDragging = true;
        card.classList.add('is-dragging');
        if (navigator.vibrate) navigator.vibrate(40);
      }, 250);
    };

    card.ontouchmove = (e) => {
      if (!isTouchDragging) {
        const touch = e.touches[0];
        if (Math.abs(touch.clientX - touchStartX) > 10 || Math.abs(touch.clientY - touchStartY) > 10) {
          clearTimeout(touchTimer);
        }
        return;
      }
      e.preventDefault();
      const touch = e.touches[0];
      const targetElement = document.elementFromPoint(touch.clientX, touch.clientY);
      const targetCard = targetElement?.closest('.service-card.is-draggable');
      
      cards.forEach(c => c.classList.remove('drag-over'));
      if (targetCard && targetCard.dataset.id !== draggedCardId) {
        targetCard.classList.add('drag-over');
      }
    };

    card.ontouchend = async (e) => {
      clearTimeout(touchTimer);
      if (isTouchDragging) {
        e.preventDefault();
        const changedTouch = e.changedTouches[0];
        const targetElement = document.elementFromPoint(changedTouch.clientX, changedTouch.clientY);
        const targetCard = targetElement?.closest('.service-card.is-draggable');
        
        cards.forEach(c => {
          c.classList.remove('is-dragging');
          c.classList.remove('drag-over');
        });

        if (targetCard && targetCard.dataset.id && targetCard.dataset.id !== draggedCardId) {
          await swapServiceItems(draggedCardId, targetCard.dataset.id);
        }
        isTouchDragging = false;
        draggedCardId = null;
      }
    };
  });
}

async function swapServiceItems(sourceId, targetId) {
  const srcIdx = state.services.findIndex(s => s.id === sourceId);
  const tgtIdx = state.services.findIndex(s => s.id === targetId);
  if (srcIdx === -1 || tgtIdx === -1) return;

  const itemA = state.services[srcIdx];
  const itemB = state.services[tgtIdx];

  state.services.splice(srcIdx, 1);
  state.services.splice(tgtIdx, 0, itemA);

  state.services.forEach((s, idx) => {
    s.order = idx + 1;
  });

  try {
    if (!itemA.isLocalFallback) {
      await updateDoc(doc(db, itemA.collectionName || 'categories', itemA.id), {
        order: itemA.order,
        updated_at: serverTimestamp()
      });
    }
    if (!itemB.isLocalFallback) {
      await updateDoc(doc(db, itemB.collectionName || 'categories', itemB.id), {
        order: itemB.order,
        updated_at: serverTimestamp()
      });
    }
    showToast('✨ ย้ายตำแหน่งบริการเรียบร้อยแล้ว', 'success');
  } catch (e) {
    console.warn('Sync drag order notice:', e.message);
  }

  renderServicesView();
  renderSidebarList();
}

window.moveServicePosition = async (id, direction) => {
  if (!state.isAdmin) return;

  const currentIdx = state.services.findIndex(s => s.id === id);
  if (currentIdx === -1) return;

  const targetIdx = currentIdx + direction;
  if (targetIdx < 0 || targetIdx >= state.services.length) return;

  const targetId = state.services[targetIdx].id;
  await swapServiceItems(id, targetId);
};

// ==========================================================================
// 👁️ Quick Visibility Toggle Engine (Admin Only)
// ==========================================================================
window.toggleServiceVisibility = async (id, currentActive) => {
  if (!state.isAdmin) return;

  const targetService = state.services.find(s => s.id === id);
  if (!targetService) return;

  const newStatus = !currentActive;
  targetService.active = newStatus;

  try {
    if (!targetService.isLocalFallback) {
      const collectionName = targetService.collectionName || 'categories';
      await updateDoc(doc(db, collectionName, id), {
        active: newStatus,
        updated_at: serverTimestamp()
      });
    }

    showToast(newStatus ? '👁️ เปิดแสดงรายการนี้แล้ว' : '👁️‍🗨️ ซ่อนรายการนี้เรียบร้อยแล้ว', 'info');
    renderServicesView();
    renderSidebarList();
    updateNotificationCenter();
  } catch (err) {
    console.error('Toggle visibility error:', err);
    showToast('ปรับสถานะไม่สำเร็จ: ' + err.message, 'danger');
  }
};

// ==========================================================================
// 📝 Staff Notes & Feedback Engine
// ==========================================================================
async function loadStaffNotes() {
  try {
    const notesSnapshot = await getDocs(collection(db, 'staff_notes'));
    const notes = [];
    notesSnapshot.forEach(docSnap => {
      notes.push({ id: docSnap.id, ...docSnap.data() });
    });
    notes.sort((a, b) => (b.created_at?.seconds || 0) - (a.created_at?.seconds || 0));
    state.staffNotes = notes;

    if (inboxCountBadge) {
      inboxCountBadge.innerText = notes.length;
      inboxCountBadge.style.display = notes.length > 0 ? 'inline-block' : 'none';
    }

    renderAdminInbox();
  } catch (err) {
    console.error('Load staff notes error:', err);
  }
}

function renderAdminInbox() {
  if (!adminInboxBody) return;

  if (state.staffNotes.length === 0) {
    adminInboxBody.innerHTML = `
      <div style="text-align: center; padding: 32px 0; color: var(--text-secondary);">
        <i data-lucide="check-circle-2" style="width: 36px; height: 36px; color: var(--apple-mint); margin-bottom: 8px;"></i>
        <p>ยังไม่มีข้อความเสนอแนะจากพนักงานในขณะนี้</p>
      </div>
    `;
    lucide.createIcons();
    return;
  }

  adminInboxBody.innerHTML = state.staffNotes.map(n => `
    <div style="padding: 12px 14px; background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); border-radius: var(--radius-md); margin-bottom: 10px;">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; margin-bottom: 6px;">
        <div>
          <span style="font-weight: 700; font-size: 0.9rem; color: #ffd60a;">${n.topic || 'ข้อเสนอแนะ'}</span>
          ${n.service_name ? `<div style="font-size: 0.76rem; color: var(--apple-teal); margin-top: 2px;">📌 บริการ: ${n.service_name}</div>` : ''}
        </div>
        <button class="btn btn-secondary" style="font-size: 0.72rem; padding: 3px 8px; color: var(--apple-mint);" onclick="window.dismissStaffNote('${n.id}')">
          <i data-lucide="check"></i> ปิดรายการ
        </button>
      </div>
      <p style="font-size: 0.84rem; line-height: 1.5; color: var(--text-primary); white-space: pre-line; background: rgba(0,0,0,0.2); padding: 8px 10px; border-radius: var(--radius-sm);">
        ${n.detail || ''}
      </p>
      <div style="display: flex; justify-content: space-between; align-items: center; margin-top: 6px; font-size: 0.72rem; color: var(--text-tertiary);">
        <span>👤 ผู้ส่ง: ${n.sender || 'เจ้าหน้าที่'}</span>
        <span>${n.created_at ? new Date(n.created_at.seconds * 1000).toLocaleString('th-TH') : ''}</span>
      </div>
    </div>
  `).join('');

  lucide.createIcons();
}

window.dismissStaffNote = async (noteId) => {
  try {
    await deleteDoc(doc(db, 'staff_notes', noteId));
    showToast('ปิดรายการเรียบร้อยแล้ว', 'success');
    await loadStaffNotes();
  } catch (err) {
    showToast('ทำรายการไม่สำเร็จ: ' + err.message, 'danger');
  }
};

window.navigateToServiceFromNotif = (serviceId) => {
  const modal = document.getElementById('notif-modal');
  if (modal) modal.classList.remove('active');
  window.openServiceDetail(serviceId);
};

// ==========================================================================
// 🔔 Responsive Smart Notification Center Engine (Categorized by Service Type)
// ==========================================================================
function updateNotificationCenter() {
  const expiringPromos = [];
  const activePromos = [];
  const latestNews = [];
  const recentMemos = [];

  const visibleServices = state.isAdmin ? 
    state.services : 
    state.services.filter(s => s.active !== false);

  visibleServices.forEach(s => {
    const promoMeta = calculatePromoStatus(s.start_date, s.end_date);
    if (s.category_type === 'promotions') {
      if (promoMeta.status === 'expiring_soon') {
        expiringPromos.push({ service: s, meta: promoMeta });
      } else if (promoMeta.status === 'active') {
        activePromos.push({ service: s, meta: promoMeta });
      }
    } else if (s.category_type === 'news') {
      latestNews.push({ service: s, meta: promoMeta });
    }

    // Scan for attached official memos across ALL services (e.g. EMS, Registered, ePacket, FUZE POST)
    if (Array.isArray(s.blocks)) {
      s.blocks.forEach(b => {
        if (b.type === 'checklist' && (b.title.includes('บันทึก') || b.title.includes('คำสั่ง') || b.id.startsWith('memo_') || b.id.startsWith('blk_pdf_'))) {
          recentMemos.push({
            service: s,
            blockTitle: b.title,
            firstDetail: Array.isArray(b.data) && b.data.length > 0 ? (typeof b.data[0] === 'string' ? b.data[0] : (b.data[0].title || '')) : (s.summary || '')
          });
        }
      });
    }
  });

  const hasAlerts = expiringPromos.length > 0 || latestNews.length > 0 || recentMemos.length > 0;
  if (notifIndicator) {
    notifIndicator.style.display = hasAlerts ? 'block' : 'none';
  }

  // Quick alert top banner for expiring promos
  if (quickAlertBanner) {
    if (expiringPromos.length > 0) {
      const topExpiring = expiringPromos[0];
      quickAlertBanner.style.display = 'block';
      quickAlertBanner.innerHTML = `
        <div style="display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; background: rgba(255, 149, 0, 0.15); border: 1px solid rgba(255, 149, 0, 0.35); border-radius: var(--radius-md); gap: 10px; cursor: pointer;" onclick="window.navigateToServiceFromNotif('${topExpiring.service.id}')">
          <div style="display: flex; align-items: center; gap: 8px;">
            <i data-lucide="alert-triangle" style="color: #ff9500; width: 18px; height: 18px; flex-shrink: 0;"></i>
            <span style="font-size: 0.84rem; font-weight: 600; color: #ffb340;">
              ⚡ <strong>โปรโมชั่นใกล้หมดเขต:</strong> ${topExpiring.service.name} (${topExpiring.meta.label})
            </span>
          </div>
          <span style="font-size: 0.76rem; color: var(--text-link); font-weight: 700; white-space: nowrap;">
            ดูเงื่อนไข &rarr;
          </span>
        </div>
      `;
      lucide.createIcons();
    } else {
      quickAlertBanner.style.display = 'none';
    }
  }

  // Helper filter checks
  const isDomestic = (s) => s.category_type === 'domestic' || s.name.includes('ในประเทศ') || s.name.includes('EMS') || s.name.includes('ลงทะเบียน') || s.name.includes('จดหมาย');
  const isIntl = (s) => s.category_type === 'international' || s.name.includes('ระหว่างประเทศ') || s.name.includes('ฟิลิปปินส์') || s.name.includes('ePacket') || s.name.includes('USA') || s.name.includes('World') || s.name.includes('Courier');

  // Compute counts for badge pills
  const countAll = expiringPromos.length + latestNews.length + recentMemos.length + activePromos.length;
  const countDomestic = [...expiringPromos, ...latestNews, ...recentMemos, ...activePromos].filter(item => isDomestic(item.service)).length;
  const countIntl = [...expiringPromos, ...latestNews, ...recentMemos, ...activePromos].filter(item => isIntl(item.service)).length;
  const countPromo = expiringPromos.length + activePromos.length;
  const countMemos = recentMemos.length;

  const countAllEl = document.getElementById('notif-count-all');
  const countDomEl = document.getElementById('notif-count-domestic');
  const countIntlEl = document.getElementById('notif-count-intl');
  const countPromoEl = document.getElementById('notif-count-promo');
  const countMemosEl = document.getElementById('notif-count-memos');

  if (countAllEl) countAllEl.innerText = countAll;
  if (countDomEl) countDomEl.innerText = countDomestic;
  if (countIntlEl) countIntlEl.innerText = countIntl;
  if (countPromoEl) countPromoEl.innerText = countPromo;
  if (countMemosEl) countMemosEl.innerText = countMemos;

  // Filter lists based on selectedNotifTab
  const activeTab = state.selectedNotifTab || 'all';

  let filteredMemos = recentMemos;
  let filteredExpiring = expiringPromos;
  let filteredNews = latestNews;
  let filteredActive = activePromos;

  if (activeTab === 'domestic') {
    filteredMemos = recentMemos.filter(item => isDomestic(item.service));
    filteredExpiring = expiringPromos.filter(item => isDomestic(item.service));
    filteredNews = latestNews.filter(item => isDomestic(item.service));
    filteredActive = activePromos.filter(item => isDomestic(item.service));
  } else if (activeTab === 'international') {
    filteredMemos = recentMemos.filter(item => isIntl(item.service));
    filteredExpiring = expiringPromos.filter(item => isIntl(item.service));
    filteredNews = latestNews.filter(item => isIntl(item.service));
    filteredActive = activePromos.filter(item => isIntl(item.service));
  } else if (activeTab === 'new_promo') {
    filteredMemos = [];
    filteredNews = [];
  } else if (activeTab === 'memos') {
    filteredExpiring = [];
    filteredNews = [];
    filteredActive = [];
  }

  let notifHtml = '';

  // 1. Attached Official Memos & Service Directives
  if (filteredMemos.length > 0) {
    notifHtml += `
      <div style="margin-bottom: 16px;">
        <div style="font-size: 0.84rem; font-weight: 700; color: #ffd60a; margin-bottom: 8px; display: flex; align-items: center; gap: 6px;">
          <i data-lucide="file-text" style="width: 16px; height: 16px; color: #ffd60a;"></i> 📜 บันทึกสั่งการ & แนวปฏิบัติที่แนบในบริการ (${filteredMemos.length})
        </div>
        ${filteredMemos.map(item => `
          <div style="padding: 12px 14px; background: rgba(255, 214, 10, 0.07); border: 1px solid rgba(255, 214, 10, 0.3); border-radius: var(--radius-md); margin-bottom: 10px; cursor: pointer; transition: var(--transition);" onclick="window.navigateToServiceFromNotif('${item.service.id}')">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; flex-wrap: wrap; gap: 6px;">
              <span style="font-size: 0.72rem; font-weight: 700; color: ${item.service.color || '#64d2ff'};">📌 ในบริการ: ${item.service.name}</span>
            </div>
            <h4 style="font-weight: 700; font-size: 0.9rem; color: #fff; margin: 0 0 4px 0; line-height: 1.4; word-break: break-word;">${item.blockTitle}</h4>
            ${item.firstDetail ? `<p style="font-size: 0.78rem; color: var(--text-secondary); line-height: 1.4; margin: 0;">${item.firstDetail}</p>` : ''}
          </div>
        `).join('')}
      </div>
    `;
  }

  // 2. Expiring Promos
  if (filteredExpiring.length > 0) {
    notifHtml += `
      <div style="margin-bottom: 16px;">
        <div style="font-size: 0.84rem; font-weight: 700; color: #ff9500; margin-bottom: 8px; display: flex; align-items: center; gap: 6px;">
          <i data-lucide="alert-triangle" style="width: 16px; height: 16px;"></i> ⚡ โปรโมชั่นใกล้หมดเขต (${filteredExpiring.length})
        </div>
        ${filteredExpiring.map(item => `
          <div style="padding: 12px 14px; background: rgba(255, 149, 0, 0.08); border: 1px solid rgba(255, 149, 0, 0.3); border-radius: var(--radius-md); margin-bottom: 10px; cursor: pointer; transition: var(--transition);" onclick="window.navigateToServiceFromNotif('${item.service.id}')">
            <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; flex-wrap: wrap; gap: 6px;">
              <span class="badge-status badge-expiring" style="font-size: 0.74rem;">${item.meta.label}</span>
            </div>
            <h4 style="font-weight: 700; font-size: 0.94rem; color: #fff; line-height: 1.4; margin: 0 0 4px 0; word-break: break-word;">${item.service.name}</h4>
            ${item.service.summary ? `<p style="font-size: 0.8rem; color: var(--text-secondary); line-height: 1.4; margin: 0;">${item.service.summary}</p>` : ''}
          </div>
        `).join('')}
      </div>
    `;
  }

  // 3. Latest News & Announcements (รวมเหตุล่าช้าต่างประเทศ & ประกาศปรับราคา)
  if (filteredNews.length > 0) {
    notifHtml += `
      <div style="margin-bottom: 16px;">
        <div style="font-size: 0.84rem; font-weight: 700; color: #64d2ff; margin-bottom: 8px; display: flex; align-items: center; gap: 6px;">
          <i data-lucide="megaphone" style="width: 16px; height: 16px;"></i> 📢 ประกาศ & การเปลี่ยนแปลงบริการล่าสุด (${filteredNews.length})
        </div>
        ${filteredNews.map(item => `
          <div style="padding: 12px 14px; background: rgba(255, 255, 255, 0.03); border: 1px solid var(--border-subtle); border-radius: var(--radius-md); margin-bottom: 10px; cursor: pointer; transition: var(--transition);" onclick="window.navigateToServiceFromNotif('${item.service.id}')">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; flex-wrap: wrap; gap: 6px;">
              <h4 style="font-weight: 700; font-size: 0.92rem; color: #fff; margin: 0; line-height: 1.4; word-break: break-word; flex: 1;">${item.service.name}</h4>
              ${item.service.start_date ? `<span class="meta-pill" style="font-size: 0.7rem; white-space: nowrap;">มีผล ${formatThaiDate(item.service.start_date)}</span>` : ''}
            </div>
            ${item.service.summary ? `<p style="font-size: 0.8rem; color: var(--text-secondary); line-height: 1.4; margin: 0;">${item.service.summary}</p>` : ''}
          </div>
        `).join('')}
      </div>
    `;
  }

  // 4. Active Promotions
  if (filteredActive.length > 0) {
    notifHtml += `
      <div>
        <div style="font-size: 0.84rem; font-weight: 700; color: var(--apple-mint); margin-bottom: 8px; display: flex; align-items: center; gap: 6px;">
          <i data-lucide="gift" style="width: 16px; height: 16px;"></i> 🎁 โปรโมชั่นที่กำลังเปิดใช้งาน (${filteredActive.length})
        </div>
        ${filteredActive.map(item => `
          <div style="padding: 10px 14px; background: rgba(48, 209, 88, 0.05); border: 1px solid rgba(48, 209, 88, 0.2); border-radius: var(--radius-md); margin-bottom: 8px; cursor: pointer; transition: var(--transition);" onclick="window.navigateToServiceFromNotif('${item.service.id}')">
            <div style="display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap;">
              <span style="font-weight: 700; font-size: 0.88rem; color: #fff; flex: 1; min-width: 180px; word-break: break-word;">${item.service.name}</span>
              <span class="badge-status badge-active" style="font-size: 0.72rem; white-space: nowrap;">${item.meta.label}</span>
            </div>
          </div>
        `).join('')}
      </div>
    `;
  }

  if (!notifHtml) {
    notifHtml = `
      <div style="text-align: center; padding: 28px 0; color: var(--text-secondary);">
        <i data-lucide="check-circle" style="width: 32px; height: 32px; color: var(--apple-mint); margin-bottom: 8px;"></i>
        <p>ไม่มีรายการแจ้งเตือนในกลุ่มนี้</p>
      </div>
    `;
  }

  notifSheetBody.innerHTML = notifHtml;
  lucide.createIcons();
  setupNotifTabButtons();
}

function setupNotifTabButtons() {
  document.querySelectorAll('#notif-tab-filter-container .notif-tab-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#notif-tab-filter-container .notif-tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.selectedNotifTab = btn.dataset.notifTab;
      updateNotificationCenter();
    };
  });
}

// ==========================================================================
// 🏷️ Category Switcher Tabs Dataset & Touch Drag-and-Drop Reordering Engine
// ==========================================================================
const DEFAULT_MAIN_CATEGORIES = [
  { id: 'all', label: 'ทั้งหมด', icon: 'layout-grid', countId: 'count-all' },
  { id: 'domestic', label: 'ในประเทศ', icon: 'map-pin', countId: 'count-domestic' },
  { id: 'international', label: 'ระหว่างประเทศ', icon: 'globe', countId: 'count-intl' },
  { id: 'coldchain', label: 'FUZE POST', icon: 'snowflake', iconColor: '#64d2ff', countId: 'count-cold' },
  { id: 'promotions', label: 'โปรโมชั่น & ส่วนลด', icon: 'gift', iconColor: '#ffd60a', countId: 'count-promos' },
  { id: 'news', label: 'ศูนย์ข่าว & ประกาศ', icon: 'megaphone', iconColor: '#ff9f0a', countId: 'count-news' }
];

function getMainCategories() {
  try {
    const savedOrder = JSON.parse(localStorage.getItem('dept_custom_category_order'));
    if (Array.isArray(savedOrder) && savedOrder.length > 0) {
      const ordered = [];
      savedOrder.forEach(catId => {
        const found = DEFAULT_MAIN_CATEGORIES.find(c => c.id === catId);
        if (found) ordered.push(found);
      });
      DEFAULT_MAIN_CATEGORIES.forEach(c => {
        if (!ordered.some(o => o.id === c.id)) ordered.push(c);
      });
      return ordered;
    }
  } catch (e) {}
  return [...DEFAULT_MAIN_CATEGORIES];
}

function renderMainCategorySwitcher() {
  const switcher = document.getElementById('main-category-switcher');
  if (!switcher) return;

  const categories = getMainCategories();
  const draggableAttr = state.isAdmin ? 'draggable="true"' : '';
  const draggableClass = state.isAdmin ? 'is-draggable-tab' : '';

  switcher.innerHTML = categories.map(cat => {
    const isActive = state.selectedMainCategory === cat.id ? 'active' : '';
    const colorStyle = cat.iconColor ? `style="color: ${cat.iconColor};"` : '';
    return `
      <button class="switcher-btn ${isActive} ${draggableClass}" data-category-type="${cat.id}" ${draggableAttr} title="${state.isAdmin ? 'แตะค้างแล้วลากเพื่อสลับตำแหน่งหมวดหมู่นี้' : ''}">
        <i data-lucide="${cat.icon}" ${colorStyle}></i> ${cat.label} <span class="badge-count" id="${cat.countId}"></span>
      </button>
    `;
  }).join('');

  lucide.createIcons();
  setupCategorySwitcherClicks();
  setupCategoryTabDragAndDrop();
}

function setupCategorySwitcherClicks() {
  document.querySelectorAll('#main-category-switcher .switcher-btn').forEach(btn => {
    btn.onclick = () => {
      if (isTouchTabDragging) return;
      document.querySelectorAll('#main-category-switcher .switcher-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.selectedMainCategory = btn.dataset.categoryType;
      state.selectedCategory = '';
      renderSidebarList();
      renderServicesView();
    };
  });
}

// Category Tabs Drag & Drop (Touch and Hold / Mouse)
let draggedTabId = null;
let touchTabDragEl = null;
let touchTabStartX = 0;
let touchTabStartY = 0;
let isTouchTabDragging = false;
let touchTabTimer = null;

function setupCategoryTabDragAndDrop() {
  if (!state.isAdmin) return;

  const tabs = document.querySelectorAll('#main-category-switcher .switcher-btn.is-draggable-tab');
  tabs.forEach(tab => {
    // Desktop Mouse Drag
    tab.ondragstart = (e) => {
      draggedTabId = tab.dataset.categoryType;
      tab.classList.add('is-dragging-tab');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', tab.dataset.categoryType);
    };

    tab.ondragover = (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      if (tab.dataset.categoryType !== draggedTabId) {
        tab.classList.add('drag-over-tab');
      }
    };

    tab.ondragleave = () => {
      tab.classList.remove('drag-over-tab');
    };

    tab.ondrop = async (e) => {
      e.preventDefault();
      tab.classList.remove('drag-over-tab');
      const targetCatId = tab.dataset.categoryType;
      if (draggedTabId && targetCatId && draggedTabId !== targetCatId) {
        await swapCategoryTabs(draggedTabId, targetCatId);
      }
    };

    tab.ondragend = () => {
      tabs.forEach(t => {
        t.classList.remove('is-dragging-tab');
        t.classList.remove('drag-over-tab');
      });
      draggedTabId = null;
    };

    // Mobile Touch & Hold Drag (200ms Long Press)
    tab.ontouchstart = (e) => {
      const touch = e.touches[0];
      touchTabStartX = touch.clientX;
      touchTabStartY = touch.clientY;
      touchTabDragEl = tab;
      draggedTabId = tab.dataset.categoryType;

      touchTabTimer = setTimeout(() => {
        isTouchTabDragging = true;
        tab.classList.add('is-dragging-tab');
        if (navigator.vibrate) navigator.vibrate(50);
        showToast(`🖐️ กำลังลากหมวดหมู่ "${tab.innerText.trim()}" - ลากไปวางที่ตำแหน่งที่ต้องการได้เลยครับ`, 'info');
      }, 200);
    };

    tab.ontouchmove = (e) => {
      if (!isTouchTabDragging) {
        const touch = e.touches[0];
        if (Math.abs(touch.clientX - touchTabStartX) > 10 || Math.abs(touch.clientY - touchTabStartY) > 10) {
          clearTimeout(touchTabTimer);
        }
        return;
      }
      e.preventDefault();
      const touch = e.touches[0];
      const targetElement = document.elementFromPoint(touch.clientX, touch.clientY);
      const targetTab = targetElement?.closest('#main-category-switcher .switcher-btn.is-draggable-tab');
      
      tabs.forEach(t => t.classList.remove('drag-over-tab'));
      if (targetTab && targetTab.dataset.categoryType !== draggedTabId) {
        targetTab.classList.add('drag-over-tab');
      }
    };

    tab.ontouchend = async (e) => {
      clearTimeout(touchTabTimer);
      if (isTouchTabDragging) {
        e.preventDefault();
        const changedTouch = e.changedTouches[0];
        const targetElement = document.elementFromPoint(changedTouch.clientX, changedTouch.clientY);
        const targetTab = targetElement?.closest('#main-category-switcher .switcher-btn.is-draggable-tab');
        
        tabs.forEach(t => {
          t.classList.remove('is-dragging-tab');
          t.classList.remove('drag-over-tab');
        });

        if (targetTab && targetTab.dataset.categoryType && targetTab.dataset.categoryType !== draggedTabId) {
          await swapCategoryTabs(draggedTabId, targetTab.dataset.categoryType);
        }
        setTimeout(() => { isTouchTabDragging = false; }, 100);
        draggedTabId = null;
      }
    };
  });
}

async function swapCategoryTabs(sourceCatId, targetCatId) {
  const currentCategories = getMainCategories();
  const srcIdx = currentCategories.findIndex(c => c.id === sourceCatId);
  const tgtIdx = currentCategories.findIndex(c => c.id === targetCatId);
  if (srcIdx === -1 || tgtIdx === -1) return;

  const [movedCat] = currentCategories.splice(srcIdx, 1);
  currentCategories.splice(tgtIdx, 0, movedCat);

  const newOrderIds = currentCategories.map(c => c.id);
  localStorage.setItem('dept_custom_category_order', JSON.stringify(newOrderIds));

  try {
    await setDoc(doc(db, 'admin_settings', 'categories_order'), {
      order: newOrderIds,
      updated_at: serverTimestamp()
    }, { merge: true });
  } catch (err) {
    console.warn('Sync custom category tab order to cloud notice:', err.message);
  }

  showToast(`✨ สลับตำแหน่งหมวดหมู่ "${movedCat.label}" เรียบร้อยแล้ว`, 'success');
  renderMainCategorySwitcher();
  renderCategoryTabsManager();
  renderServicesView();
}

function renderCategoryTabsManager() {
  const container = document.getElementById('category-tab-manager-list');
  if (!container) return;

  const categories = getMainCategories();
  container.innerHTML = categories.map((cat, idx) => {
    const colorStyle = cat.iconColor ? `style="color: ${cat.iconColor};"` : '';
    return `
      <div style="display: flex; align-items: center; justify-content: space-between; padding: 7px 12px; background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); border-radius: var(--radius-sm);">
        <div style="display: flex; align-items: center; gap: 8px;">
          <span style="font-size: 0.76rem; font-weight: 700; color: #ffd60a; min-width: 20px;">#${idx + 1}</span>
          <i data-lucide="${cat.icon}" ${colorStyle} style="width: 15px; height: 15px;"></i>
          <span style="font-size: 0.84rem; font-weight: 600; color: var(--text-primary);">${cat.label}</span>
        </div>
      </div>
    `;
  }).join('');

  lucide.createIcons();
}

window.moveCategoryTabPosition = async (catId, direction) => {
  if (!state.isAdmin) return;
  const categories = getMainCategories();
  const currentIdx = categories.findIndex(c => c.id === catId);
  if (currentIdx === -1) return;

  const targetIdx = currentIdx + direction;
  if (targetIdx < 0 || targetIdx >= categories.length) return;

  const [moved] = categories.splice(currentIdx, 1);
  categories.splice(targetIdx, 0, moved);

  const newOrderIds = categories.map(c => c.id);
  localStorage.setItem('dept_custom_category_order', JSON.stringify(newOrderIds));

  try {
    await setDoc(doc(db, 'admin_settings', 'categories_order'), {
      order: newOrderIds,
      updated_at: serverTimestamp()
    }, { merge: true });
  } catch (err) {
    console.warn('Sync tab order notice:', err.message);
  }

  showToast(`✨ สลับตำแหน่งแท็บ "${moved.label}" เรียบร้อยแล้ว`, 'success');
  renderMainCategorySwitcher();
  renderCategoryTabsManager();
  renderServicesView();
};

window.resetCategoryTabsOrder = async () => {
  if (!state.isAdmin) return;
  localStorage.removeItem('dept_custom_category_order');
  try {
    await deleteDoc(doc(db, 'admin_settings', 'categories_order'));
  } catch (e) {}
  showToast('🔄 รีเซ็ตลำดับแท็บหมวดหมู่เป็นค่าเริ่มต้นแล้ว', 'info');
  renderMainCategorySwitcher();
  renderCategoryTabsManager();
  renderServicesView();
};

