window.handleUploadPdfToLegoBlock = (event, blockIdx) => {
  const file = event.target.files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = () => {
    saveCurrentEditorStateToMemory();
    const pdfDataUrl = reader.result;
    const block = state.currentEditingBlocks[blockIdx];
    if (block) {
      if (!Array.isArray(block.data)) block.data = [];
      block.data.push({
        title: file.name,
        url: pdfDataUrl
      });
      showToast(`📁 แนบไฟล์ PDF "${file.name}" เรียบร้อยแล้ว`, 'success');
      renderLegoEditorBlocks();
    }
  };
  reader.readAsDataURL(file);
};

window.handleAttachPdfInLego = (event, inputEl) => {
  const file = event.target.files?.[0];
  if (!file) return;
  const parent = inputEl.closest('.links-builder-container > div') || inputEl.closest('div');
  const titleInput = parent?.querySelector('.link-title-input');
  const urlInput = parent?.querySelector('.link-url-input');

  const reader = new FileReader();
  reader.onload = () => {
    if (titleInput && !titleInput.value) titleInput.value = file.name;
    if (urlInput) urlInput.value = reader.result;
    showToast(`📁 แนบไฟล์ PDF "${file.name}" สำเร็จ`, 'success');
  };
  reader.readAsDataURL(file);
};

