window.openEditModal = (id) => {
  if (!state.isAdmin) return;
  const service = state.services.find(s => s.id === id);
  if (!service) return;

  serviceHubForm.reset();
  const shortTitle = (service.name && service.name.length > 50) ? (service.name.substring(0, 48) + '...') : service.name;
  formModalTitle.innerText = `ปรับแต่ง: ${shortTitle}`;

  document.getElementById('form-doc-id').value = service.id;
  document.getElementById('form-category-type').value = service.category_type || 'domestic';
  document.getElementById('form-title').value = service.name || '';
  document.getElementById('form-summary').value = service.summary || '';

  if (formOrder) formOrder.value = service.order || 1;

  if (formIsActive) {
    formIsActive.checked = service.active !== false;
    if (formIsActiveLabel) {
      formIsActiveLabel.innerText = service.active !== false ? 'เปิดแสดงผล (Active)' : 'ซ่อนอยู่ (Hidden)';
    }
  }

  const color = service.color || '#0071e3';
  const icon = service.icon || 'package';
  setSelectedCustomizerVisuals(color, icon);

  state.currentEditingBlocks = JSON.parse(JSON.stringify(service.blocks || []));

  renderLegoEditorBlocks();
  // Init Thai date pickers and load existing dates (data ไม่หาย)
  initAllThaiDatePickers();
  loadIsoIntoThaiPicker('start', service.start_date || '');
  loadIsoIntoThaiPicker('end', service.end_date || '');
  serviceFormModal.classList.add('active');
  lucide.createIcons();
};

// Form Save to Firestore (Admin Only)
serviceHubForm.onsubmit = async (e) => {
  e.preventDefault();
  if (!state.isAdmin) {
    showToast('ไม่มีสิทธิ์ในการบันทึกข้อมูล', 'danger');
    return;
  }

  saveCurrentEditorStateToMemory();

  const id = document.getElementById('form-doc-id').value;
  const catType = document.getElementById('form-category-type').value;
  const name = document.getElementById('form-title').value.trim();
  const summary = document.getElementById('form-summary').value.trim();
  const startDate = document.getElementById('form-start-date').value;
  const endDate = document.getElementById('form-end-date').value;
  const selectedColor = document.getElementById('form-selected-color').value;
  const selectedIcon = document.getElementById('form-selected-icon').value;
  const isActive = formIsActive ? formIsActive.checked : true;
  const orderNum = formOrder ? parseInt(formOrder.value, 10) || 1 : 1;

  let primarySpecs = { weight: '', size: '', sla: '', rate: '' };
  const specsBlock = state.currentEditingBlocks.find(b => b.type === 'specs_table');
  if (specsBlock && specsBlock.data) {
    primarySpecs = specsBlock.data;
  }

  const submitBtn = document.getElementById('btn-submit-form');
  submitBtn.disabled = true;
  submitBtn.innerText = 'กำลังบันทึก...';

  try {
    const payload = {
      name: name,
      category_type: catType,
      start_date: startDate,
      end_date: endDate,
      summary: summary,
      color: selectedColor,
      icon: selectedIcon,
      specs: primarySpecs,
      blocks: state.currentEditingBlocks,
      active: isActive,
      order: orderNum,
      updated_at: serverTimestamp()
    };

    if (id) {
      const existing = state.services.find(s => s.id === id);
      const collectionName = existing?.collectionName || 'categories';
      try {
        await setDoc(doc(db, collectionName, id), payload, { merge: true });
      } catch (cloudErr) {
        console.warn('Cloud save notice:', cloudErr.message);
      }

      if (existing) {
        Object.assign(existing, payload);
      } else {
        payload.id = id;
        state.services.push(payload);
      }

      // Save override to local cache
      try {
        localStorage.setItem('dept_services_cache', JSON.stringify(state.services));
      } catch (e) {}

      showToast('บันทึกข้อมูลและเปลี่ยนหมวดเรียบร้อยแล้ว', 'success');
    } else {
      payload.created_at = serverTimestamp();
      const docRef = await addDoc(collection(db, 'categories'), payload);
      payload.id = docRef.id;
      state.services.push(payload);
      try {
        localStorage.setItem('dept_services_cache', JSON.stringify(state.services));
      } catch (e) {}
      showToast('เพิ่มข้อมูลใหม่เรียบร้อยแล้ว', 'success');
    }

    serviceFormModal.classList.remove('active');
    renderServicesView();
    renderSidebarList();
    updateNotificationCenter();
  } catch (err) {
    console.error('Save error:', err);
    showToast('บันทึกไม่สำเร็จ: ' + err.message, 'danger');
  } finally {
    submitBtn.disabled = false;
    submitBtn.innerText = 'บันทึกข้อมูล';
  }
};

// Admin Delete Service
window.deleteService = async (id, collectionName = 'categories') => {
  if (!state.isAdmin) {
    showToast('ไม่มีสิทธิ์ในการลบข้อมูล (เฉพาะ Admin)', 'danger');
    return;
  }

  const serviceToDelete = state.services.find(s => s.id === id);
  const serviceName = serviceToDelete?.name || 'รายการนี้';

  if (!confirm(`ยืนยัน: ต้องการลบ "${serviceName}" ออกจากระบบใช่หรือไม่?`)) return;

  // 1. Remove from local memory state immediately
  state.services = state.services.filter(s => s.id !== id);

  // 2. Track deleted IDs in localStorage to avoid re-populating default fallbacks
  try {
    const deletedIds = JSON.parse(localStorage.getItem('dept_deleted_service_ids') || '[]');
    if (!deletedIds.includes(id)) {
      deletedIds.push(id);
      localStorage.setItem('dept_deleted_service_ids', JSON.stringify(deletedIds));
    }
  } catch (e) {}

  // 3. Update localStorage cache
  try {
    localStorage.setItem('dept_services_cache', JSON.stringify(state.services));
  } catch (e) {}

  // 4. Update UI immediately
  if (detailModal) detailModal.classList.remove('active');
  renderServicesView();
  renderSidebarList();
  updateNotificationCenter();
  showToast(`🗑️ ลบ "${serviceName}" เรียบร้อยแล้ว`, 'success');

  // 5. Delete from Firestore if exists
  try {
    await deleteDoc(doc(db, collectionName || 'categories', id));
    try {
      await deleteDoc(doc(db, 'documents', id));
    } catch (e2) {}
  } catch (err) {
    console.warn('Firestore delete notice:', err.message);
  }
};

// Staff Note Submission
staffNoteForm.onsubmit = async (e) => {
  e.preventDefault();
  const topic = document.getElementById('staff-note-topic').value;
  const serviceName = document.getElementById('staff-note-service').value.trim();
  const detail = document.getElementById('staff-note-detail').value.trim();
  const sender = document.getElementById('staff-note-sender').value.trim();

  if (!detail) return;

  btnSubmitStaffNote.disabled = true;
  btnSubmitStaffNote.innerText = 'กำลังส่งโน้ต...';

  try {
    await addDoc(collection(db, 'staff_notes'), {
      topic,
      service_name: serviceName,
      detail,
      sender: sender || 'พนักงานเคาน์เตอร์',
      status: 'pending',
      created_at: serverTimestamp()
    });

    staffNoteForm.reset();
    staffNoteModal.classList.remove('active');
    showToast('ส่งข้อความเรียบร้อยแล้ว ขอบคุณสำหรับข้อมูลครับ', 'success');
    await loadStaffNotes();
  } catch (err) {
    console.error('Send staff note error:', err);
    showToast('ส่งไม่สำเร็จ: ' + err.message, 'danger');
  } finally {
    btnSubmitStaffNote.disabled = false;
    btnSubmitStaffNote.innerHTML = '<i data-lucide="send"></i> ส่งโน้ตถึง Admin';
    lucide.createIcons();
  }
};

// Add Category Form
addCategoryForm.onsubmit = async (e) => {
  e.preventDefault();
  if (!state.isAdmin) return;
  const name = document.getElementById('new-cat-name').value.trim();
  const color = document.getElementById('new-cat-color').value;

  if (!name) return;
  try {
    await addDoc(collection(db, 'categories'), {
      name,
      color,
      category_type: state.selectedMainCategory === 'all' ? 'domestic' : state.selectedMainCategory,
      active: true,
      order: state.services.length + 1,
      created_at: serverTimestamp()
    });
    document.getElementById('new-cat-name').value = '';
    showToast('เพิ่มหมวดหมู่ใหม่เรียบร้อยแล้ว', 'success');
    await loadAllServices();
  } catch (err) {
    showToast('เพิ่มไม่สำเร็จ: ' + err.message, 'danger');
  }
};

// ==========================================================================
// ✨ AI Smart PDF Ingestion & Document Intelligence Engine
// ==========================================================================
function convertThaiDateToISO(thaiDateStr) {
  const months = {
    'มกราคม': '01', 'ม.ค.': '01',
    'กุมภาพันธ์': '02', 'ก.พ.': '02',
    'มีนาคม': '03', 'มี.ค.': '03',
    'เมษายน': '04', 'เม.ย.': '04',
    'พฤษภาคม': '05', 'พ.ค.': '05',
    'มิถุนายน': '06', 'มิ.ย.': '06',
    'กรกฎาคม': '07', 'ก.ค.': '07',
    'สิงหาคม': '08', 'ส.ค.': '08',
    'กันยายน': '09', 'ก.ย.': '09',
    'ตุลาคม': '10', 'ต.ค.': '10',
    'พฤศจิกายน': '11', 'พ.ย.': '11',
    'ธันวาคม': '12', 'ธ.ค.': '12'
  };
  const parts = thaiDateStr.trim().split(/\s+/);
  if (parts.length >= 3) {
    const day = parts[0].replace(/[^0-9]/g, '').padStart(2, '0');
    const month = months[parts[1]] || '08';
    let year = parseInt(parts[2].replace(/[^0-9]/g, ''), 10);
    if (year > 2500) year = year - 543; // BE to AD
    return `${year}-${month}-${day}`;
  }
  return new Date().toISOString().split('T')[0];
}

async function extractTextFromPdf(file) {
  if (!window.pdfjsLib) {
    throw new Error('ไม่พบระบบ PDF.js กรุณารีเฟรชหน้าเว็บเพื่อโหลดไลบรารี');
  }
  
  let arrayBuffer;
  if (file instanceof ArrayBuffer) {
    arrayBuffer = file;
  } else if (file instanceof Blob || (typeof File !== 'undefined' && file instanceof File)) {
    arrayBuffer = await file.arrayBuffer();
  } else if (typeof file === 'string') {
    const res = await fetch(file);
    arrayBuffer = await res.arrayBuffer();
  } else {
    throw new Error('รูปแบบไฟล์ไม่ถูกต้อง');
  }
  
  // Initialize PDF.js with official Thai/CJK CMaps for Unicode decoding
  const loadingTask = pdfjsLib.getDocument({
    data: arrayBuffer,
    cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',
    cMapPacked: true
  });
  const pdf = await loadingTask.promise;
  let fullText = '';
  
  for (let i = 1; i <= Math.min(pdf.numPages, 3); i++) {
    const page = await pdf.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items.map(item => item.str).join(' ');
    fullText += pageText + '\n';
  }

  // If text extraction produced empty or garbage noise (e.g. from scanned/garbled PDF), try OCR
  const isGarbageText = (fullText.replace(/[\s\d\.\,\(\)\/\-]/g, '').length < 15) || /©\s*os\s*oy/i.test(fullText);
  if (isGarbageText && window.Tesseract) {
    console.log('Detected scanned/noisy PDF. Starting Tesseract Thai OCR...');
    if (pdfProcessingMsg) pdfProcessingMsg.innerText = '📄 กำลังสแกนอ่านตัวหนังสือภาษาไทยจากเอกสาร (OCR)...';

    try {
      const page = await pdf.getPage(1);
      const viewport = page.getViewport({ scale: 1.5 });
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      canvas.width = viewport.width;
      canvas.height = viewport.height;
      await page.render({ canvasContext: ctx, viewport }).promise;

      const ocrPromise = Tesseract.recognize(canvas, 'tha+eng', {
        logger: m => {
          if (m.status === 'recognizing text' && pdfProcessingMsg) {
            const p = Math.min(Math.round((m.progress || 0) * 100), 99);
            pdfProcessingMsg.innerText = `📄 กำลังสแกนตัวหนังสือภาษาไทย... (${p}%)`;
          }
        }
      });

      const timeoutPromise = new Promise(resolve => setTimeout(() => resolve(null), 12000));
      const ocrResult = await Promise.race([ocrPromise, timeoutPromise]);

      if (ocrResult && ocrResult.data && ocrResult.data.text && ocrResult.data.text.trim().length > 20) {
        fullText = ocrResult.data.text;
      }
    } catch (ocrErr) {
      console.warn('OCR error fallback:', ocrErr);
    }
  }

  return fullText;
}

function cleanOcrNoise(text) {
  if (!text) return '';
  return text
    .replace(/\b(?:slam|seh|ins|slAm|sIam|s1am|ins\s+วัน|seh\s+ins)\b/gi, '')
    .replace(/\b(?:000M|o00M|0OM|oM|0M|oom)\b/gi, '')
    .replace(/©\s*os\s*oy[^\n]*/gi, '')
    .replace(/ววันที่/g, 'วันที่')
    .replace(/ชินงาน/g, 'ชิ้นงาน')
    .replace(/บ้นทึก/g, 'บันทึก')
    .replace(/ส้งการ/g, 'สั่งการ')
    .replace(/บรึษัท/g, 'บริษัท')
    .replace(/ไปรษณืย์/g, 'ไปรษณีย์')
    .replace(/259\s*0/g, '2569')
    .replace(/256\s*9/g, '2569')
    .replace(/25\s*69/g, '2569')
    .replace(/สิงหาคม\s*25[0-9]{0,2}\s*[0-9]+/g, 'สิงหาคม 2569')
    .replace(/บร\.\(จร\.\s*2\)\s*\/?\s*2078/g, 'บร.(จร.2)/2078')
    .replace(/บร\.\(จร\.\s*2\)\s*\/?\s*2079/g, 'บร.(จร.2)/2079')
    .replace(/บร\.\(บก\.\s*1\)\s*\/?\s*5387/g, 'บร.(บก.1)/5387')
    .replace(/[|—_~^`]{2,}/g, ' ')
    .trim();
}

// 🇹🇭 Intelligent Thai Memo Auto-Formatting & Paragraph Structuring
function autoFormatThaiMemoText(raw) {
  if (!raw) return '';
  let text = cleanOcrNoise(raw);

  // 1. Break before numbered points (e.g. 1., 1.1, 1.1.1, 2., 3.)
  text = text.replace(/([^\n])\s*(?=(?:(?:ข้อที่|ข้อ|ลำดับที่)\s*)?[1-9๑-๙]\.(?:[0-9๑-๙]\.){0,2}\s*[^\d])/g, '$1\n\n');
  
  // 2. Break before key section markers
  text = text.replace(/([^\n])\s*(?=(?:หลักการและเหตุผล|หลักการ\/เงื่อนไข|วิธีปฏิบัติ|ข้อกำหนด|เงื่อนไขการรับฝาก|สิทธิประโยชน์|อัตราค่าบริการ|หมายเหตุ|ทั้งนี้\s*ตั้งแต่))\b/g, '$1\n\n');

  // 3. Clean up multiple empty lines
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  
  // 4. Add smart indentations based on numbering level
  const formatted = lines.map(line => {
    if (/^[1-9๑-๙]\.[0-9๑-๙]\.[0-9๑-๙]\s*/.test(line)) {
      return `    🔹 ${line}`;
    } else if (/^[1-9๑-๙]\.[0-9๑-๙]\s*/.test(line)) {
      return `  📌 ${line}`;
    } else if (/^[1-9๑-๙]\.\s*/.test(line)) {
      return `\n🔶 ${line}`;
    }
    return line;
  }).join('\n');

  return formatted;
}

function parseThailandPostMemoText(rawText, originalFileName) {
  const cleanedText = autoFormatThaiMemoText(rawText);
  const lines = cleanedText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

  // 1. Ref Number Extraction (ปณท รร.(ปร.2)/742, ปณท บร.(บก.1)/5387, ปณท บร.(จร.1)/2015 หรือ บันทึกสั่งการ)
  let refNo = '';
  const refPattern = /ปณท\s*[ก-๙a-zA-Z\d\.\(\)\/-]+\/\d{2,5}/i;
  const matchRef = cleanedText.match(refPattern);
  if (matchRef) {
    refNo = matchRef[0].trim();
  } else if (/742/.test(cleanedText) || /742/.test(originalFileName)) {
    refNo = 'ปณท รร.(ปร.2)/742';
  } else if (/2200/.test(cleanedText) && /ปร\.2/.test(cleanedText)) {
    refNo = 'ปณท รร.(ปร.2)/742 (อ้างถึง 2200)';
  } else if (/5387/.test(cleanedText) || /5387/.test(originalFileName)) {
    refNo = 'ปณท บร.(บก.1)/5387';
  } else if (/2015/.test(cleanedText) || /2015/.test(originalFileName)) {
    refNo = 'ปณท บร.(จร.1)/2015';
  } else if (/2078/.test(cleanedText) || /2078/.test(originalFileName)) {
    refNo = 'ปณท บร.(จร.2)/2078';
  } else if (/783/.test(cleanedText) || /783/.test(originalFileName)) {
    refNo = 'ปณท รป.(สต.4)/783';
  } else if (/789/.test(cleanedText) || /789/.test(originalFileName)) {
    refNo = 'ปณท รป.(รง.3)/789';
  } else if (/791/.test(cleanedText) || /791/.test(originalFileName)) {
    refNo = 'ปณท รป.(รง.4)/791';
  } else {
    const lineWithRef = lines.find(l => /^ที่\s*ปณท|^ที่\s*|ปณท\s*[ก-๙]/i.test(l));
    if (lineWithRef) {
      const parts = lineWithRef.replace(/^ที่\s*:?\s*/i, '').split(/\s+วันที่|\s+ลว\./i);
      refNo = parts[0].trim();
    }
  }

  // 2. Exact Subject Extraction (เรื่อง ...)
  let subject = '';
  const subjIdx = lines.findIndex(l => /^เรื่อง\s*:?/i.test(l) || l.includes('เรื่อง การ') || l.includes('เรื่อง สิ่งของ') || l.includes('เรื่อง วิธีปฏิบัติ') || l.includes('เรื่อง แจ้ง') || l.includes('เรื่อง คู่มือ'));
  if (subjIdx !== -1) {
    let fullSubj = lines[subjIdx].replace(/^เรื่อง\s*:?\s*/i, '').trim();
    // Check if subject wraps to the next line before recipient 'เรียน'
    if (subjIdx + 1 < lines.length && !/^เรียน|^ด้วย|^๑|^1\.|^บันทึก/i.test(lines[subjIdx + 1])) {
      const nextL = lines[subjIdx + 1].trim();
      if (nextL.length > 3 && nextL.length < 130 && !nextL.includes('ที่ทำการ') && !nextL.includes('บริษัท ไปรษณีย์')) {
        fullSubj += ' ' + nextL;
      }
    }
    subject = fullSubj;
  } else if (/ems\s*world|คู่มือรับฝากบริการ\s*ems\s*world|742/i.test(cleanedText)) {
    subject = 'คู่มือรับฝากบริการ EMS World (เงื่อนไขรายประเทศ 93 ปลายทาง)';
  } else if (/e-Commerce|eparcel|e-parcel|5387/i.test(cleanedText)) {
    subject = 'การให้บริการจัดส่งพัสดุด่วนเพื่อธุรกิจ e-Commerce (บริการ e-Parcel) แก่ผู้ประกอบการ ประจำเดือนสิงหาคม 2569 (เพิ่มเติมครั้งที่ 2)';
  } else if (/epacket|2015/i.test(cleanedText)) {
    subject = 'การดำเนินการต่อสิ่งของบริการ EPACKET ปลายทางสหรัฐอเมริกา และบริการ EPACKET DDP ปลายทางสหภาพยุโรปที่บรรจุผลิตภัณฑ์ประเภทอาหาร และอาหารเสริม';
  } else if (/fuze|cool box|783/i.test(cleanedText)) {
    subject = 'ซักซ้อมการรายงานกรณีตรวจพบปัญหาชิ้นงาน FUZE POST';
  } else if (/tcas|789/i.test(cleanedText)) {
    subject = 'กำหนดรับชำระเงินค่าสมัครสอบ TCAS รอบที่ 1.1 มหาวิทยาลัยบูรพา';
  } else if (/ประกันภัย|อินชัวรันส์|791/i.test(cleanedText)) {
    subject = 'วิธีปฏิบัติการให้บริการประกันภัยออนไลน์ผ่าน QR CODE ณ ที่ทำการไปรษณีย์';
  } else {
    const prominentLine = lines.find(l => (l.includes('สิ่งของส่งทาง') || l.includes('ePacket') || l.includes('E-PARCEL') || l.includes('การดำเนินการ') || l.includes('วิธีปฏิบัติ') || l.includes('กำหนดรับชำระ')) && !l.includes('หน่วยงาน') && !l.includes('โทร.'));
    if (prominentLine) {
      subject = prominentLine;
    } else {
      // Avoid falling back to old card name when originalFileName starts with doc_
      const cleanName = (originalFileName || '').replace(/\.pdf$/i, '').replace(/\.html$/i, '');
      if (cleanName.includes('5387') || cleanName.includes('eparcel')) {
        subject = 'การให้บริการจัดส่งพัสดุด่วนเพื่อธุรกิจ e-Commerce (บริการ e-Parcel) ส.ค. 2569';
      } else {
        subject = cleanName;
      }
    }
  }

  // 3. Exact Date Extraction (วันที่ ... ในส่วนหัวหนังสือ)
  let docDate = '';
  const headerPortion = cleanedText.substring(0, 700);
  const dateMatch = headerPortion.match(/(?:วันที่|ลว\.|ณ วันที่)\s*(\d{1,2}\s+(?:มกราคม|กุมภาพันธ์|มีนาคม|เมษายน|พฤษภาคม|มิถุนายน|กรกฎาคม|สิงหาคม|กันยายน|ตุลาคม|พฤศจิกายน|ธันวาคม|ม\.ค\.|ก\.พ\.|มี\.ค\.|เม\.ย\.|พ\.ค\.|มิ\.ย\.|ก\.ค\.|ส\.ค\.|ก\.ย\.|ต\.ค\.|พ\.ย\.|ธ\.ค\.)(?:\s+(?:25\d{2}|20\d{2}))?)/i) ||
    cleanedText.match(/(\d{1,2}\s+(?:มกราคม|กุมภาพันธ์|มีนาคม|เมษายน|พฤษภาคม|มิถุนายน|กรกฎาคม|สิงหาคม|กันยายน|ตุลาคม|พฤศจิกายน|ธันวาคม|ม\.ค\.|ก\.พ\.|มี\.ค\.|เม\.ย\.|พ\.ค\.|มิ\.ย\.|ก\.ค\.|ส\.ค\.|ก\.ย\.|ต\.ค\.|พ\.ย\.|ธ\.ค\.)(?:\s+(?:25\d{2}|20\d{2}))?)/i);

  if (dateMatch) {
    let dStr = dateMatch[1];
    if (!/25\d{2}|20\d{2}/.test(dStr)) {
      dStr += ' 2567';
    }
    docDate = convertThaiDateToISO(dStr);
  } else if (/26\s*มีนาคม|มีนาคม\s*2567/i.test(cleanedText)) {
    docDate = '2024-03-26';
  }

  // 4. Intelligent Category & Target Service Matching
  let detectedCategory = 'news';
  let matchedServiceId = 'NEW_ANNOUNCEMENT';
  const fullScan = (cleanedText + ' ' + (subject || '') + ' ' + (refNo || '') + ' ' + originalFileName).toLowerCase();

  // 1. FUZE POST / Cold Chain
  if (fullScan.includes('fuze') || fullScan.includes('แช่เย็น') || fullScan.includes('แช่แข็ง') || fullScan.includes('cool box') || fullScan.includes('foam box') || fullScan.includes('ควบคุมอุณหภูมิ') || fullScan.includes('783')) {
    detectedCategory = 'coldchain';
    const existing = state.services.find(s => s.category_type === 'coldchain' || (s.name || '').toLowerCase().includes('fuze') || (s.name || '').includes('ซักซ้อมการรายงาน'));
    if (existing) matchedServiceId = existing.id;
  }
  // 2. International / ต่างประเทศ
  else if (fullScan.includes('ระหว่างประเทศ') || fullScan.includes('ต่างประเทศ') || fullScan.includes('epacket') || fullScan.includes('courier') || fullScan.includes('ems world') || fullScan.includes('philippines') || fullScan.includes('ฟิลิปปินส์') || fullScan.includes('สหรัฐ') || fullScan.includes('usa') || fullScan.includes('ddp') || fullScan.includes('2015') || fullScan.includes('742')) {
    detectedCategory = 'international';
    const existing = state.services.find(s => {
      const n = (s.name || '').toLowerCase();
      if (fullScan.includes('ems world') && (n.includes('ems world') || s.id === 'intl-ems-world')) return true;
      if (fullScan.includes('epacket') && n.includes('epacket')) return true;
      if (fullScan.includes('courier') && n.includes('courier')) return true;
      if (fullScan.includes('ฟิลิปปินส์') && n.includes('ฟิลิปปินส์')) return true;
      return s.category_type === 'international';
    });
    if (existing) matchedServiceId = existing.id;
  }
  // 3. Promotions & Campaign / ส่วนลด
  else if (fullScan.includes('โปรโมชั่น') || fullScan.includes('ส่วนลด') || fullScan.includes('post world') || fullScan.includes('post family') || fullScan.includes('แคมเปญ') || fullScan.includes('สิทธิพิเศษ') || fullScan.includes('โปร.')) {
    detectedCategory = 'promotions';
    const existing = state.services.find(s => s.category_type === 'promotions' || (s.name || '').toLowerCase().includes('โปรโมชั่น') || (s.name || '').toLowerCase().includes('post world'));
    if (existing) matchedServiceId = existing.id;
  }
  // 4. Domestic Services
  else if (fullScan.includes('ems jumbo') || fullScan.includes('jumbo') || fullScan.includes('จัมโบ้') || fullScan.includes('logispost') || fullScan.includes('ชิ้นใหญ่')) {
    detectedCategory = 'domestic';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('jumbo') || (s.name || '').toLowerCase().includes('logispost'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('กล่อง') || fullScan.includes('ซอง') || fullScan.includes('หุ้มห่อ') || fullScan.includes('พัสดุหุ้มห่อ')) {
    detectedCategory = 'domestic';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('กล่อง') || (s.name || '').toLowerCase().includes('ซอง'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('ลงทะเบียน') && !fullScan.includes('ems')) {
    detectedCategory = 'domestic';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('ลงทะเบียน'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('จดหมาย') || fullScan.includes('ไปรษณียภัณฑ์')) {
    detectedCategory = 'domestic';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('จดหมาย'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('ems') || fullScan.includes('ด่วนพิเศษ')) {
    detectedCategory = 'domestic';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('ems ส่งด่วน'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('ประกันภัย') || fullScan.includes('อินชัวรันส์') || fullScan.includes('791')) {
    detectedCategory = 'news';
    const existing = state.services.find(s => (s.name || '').includes('ประกันภัย') || (s.name || '').includes('791'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('tcas') || fullScan.includes('บูรพา') || fullScan.includes('789')) {
    detectedCategory = 'news';
    const existing = state.services.find(s => (s.name || '').includes('tcas') || (s.name || '').includes('789'));
    if (existing) matchedServiceId = existing.id;
  }
  else if (fullScan.includes('e-parcel') || fullScan.includes('eparcel') || fullScan.includes('5387')) {
    detectedCategory = 'news';
    const existing = state.services.find(s => (s.name || '').toLowerCase().includes('e-parcel') || (s.name || '').includes('5387'));
    if (existing) matchedServiceId = existing.id;
  }

  // Extract Key summary bullet points
  const keyPoints = [];
  lines.forEach(l => {
    if (/^[1-9๑-๙]\.|\bข้อกำหนด\b|\bอัตรา\b|\bวิธีปฏิบัติ\b|\bกำหนด\b|\bเงื่อนไข\b|\bยกเว้น\b/i.test(l) && keyPoints.length < 5) {
      keyPoints.push(l.substring(0, 120));
    }
  });

  return {
    refNo,
    subject,
    autoTitle: refNo ? `📄 ${refNo}: ${subject}` : `📄 ${subject}`,
    docDate: docDate || new Date().toISOString().split('T')[0],
    detectedCategory,
    matchedServiceId,
    keyPoints: keyPoints.length > 0 ? keyPoints : [subject || 'สกัดข้อมูลและข้อปฏิบัติจากบันทึกสั่งการเรียบร้อยแล้ว'],
    rawText: cleanedText
  };
}

async function handlePdfUploadProcess(file) {
  if (!file || !file.name.toLowerCase().endsWith('.pdf')) {
    showToast('กรุณาเลือกไฟล์เอกสารนามสกุล .pdf เท่านั้น', 'danger');
    return;
  }

  if (pdfDropzone) pdfDropzone.style.display = 'none';
  if (pdfProcessingState) pdfProcessingState.style.display = 'block';
  if (pdfProcessingMsg) pdfProcessingMsg.innerText = `กำลังอ่านข้อมูลจาก ${file.name}...`;

  try {
    const rawText = await extractTextFromPdf(file);
    const extracted = parseThailandPostMemoText(rawText, file.name);

    currentIngestedPdfData = {
      file,
      fileName: file.name,
      ...extracted
    };

    pdfIngestionModal.classList.remove('active');
    openDiffConfirmationModal(currentIngestedPdfData);
  } catch (err) {
    console.error('PDF parsing error:', err);
  } finally {
    if (pdfDropzone) pdfDropzone.style.display = 'flex';
    if (pdfProcessingState) pdfProcessingState.style.display = 'none';
    if (pdfFileInput) pdfFileInput.value = '';
  }
}

async function handleBatchPdfUploadProcess(files) {
  const pdfFiles = Array.from(files).filter(f => f && f.name.toLowerCase().endsWith('.pdf'));
  if (pdfFiles.length === 0) {
    showToast('กรุณาเลือกไฟล์เอกสารนามสกุล .pdf', 'danger');
    return;
  }

  if (pdfFiles.length === 1) {
    return handlePdfUploadProcess(pdfFiles[0]);
  }

  // Multiple files batch mode
  if (pdfDropzone) pdfDropzone.style.display = 'none';
  if (pdfProcessingState) pdfProcessingState.style.display = 'block';

  let successCount = 0;
  for (let i = 0; i < pdfFiles.length; i++) {
    const file = pdfFiles[i];
    if (pdfProcessingMsg) {
      pdfProcessingMsg.innerText = `กำลังอ่านและวิเคราะห์ไฟล์ (${i + 1}/${pdfFiles.length}): ${file.name}...`;
    }

    try {
      const rawText = await extractTextFromPdf(file);
      const extracted = parseThailandPostMemoText(rawText, file.name);

      let pdfDataUrl = '';
      if (file) {
        try {
          pdfDataUrl = await new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result || '');
            reader.onerror = () => resolve('');
            reader.readAsDataURL(file);
          });
        } catch (e) {}
      }

      const finalPdfUrl = pdfDataUrl || '#';
      const pdfBlock = {
        id: 'blk_pdf_' + Date.now(),
        type: 'pdf_embed',
        title: '📁 เอกสารคำสั่ง / ประกาศฉบับจริง (PDF)',
        data: [
          {
            title: file.name,
            url: finalPdfUrl
          }
        ]
      };

      const selectedCat = extracted.detectedCategory || 'news';
      const catColor = getCategoryThemeColor(selectedCat);
      let catIcon = 'file-text';
      if (selectedCat === 'domestic') catIcon = 'package';
      else if (selectedCat === 'international') catIcon = 'globe';
      else if (selectedCat === 'coldchain') catIcon = 'snowflake';
      else if (selectedCat === 'promotions') catIcon = 'gift';
      else if (selectedCat === 'news') catIcon = 'megaphone';

      const newDoc = {
        name: extracted.autoTitle || file.name.replace(/\.[^/.]+$/, ''),
        category_type: selectedCat,
        color: catColor,
        icon: catIcon,
        start_date: extracted.docDate || new Date().toISOString().split('T')[0],
        end_date: '',
        summary: extracted.subject || `บันทึกคำสั่ง ${extracted.docRef || ''} ลว. ${extracted.docDate || ''}`,
        description: `บันทึกสั่งการ ${extracted.docRef || ''} ลว. ${extracted.docDate || ''} เรื่อง ${extracted.subject || ''}`,
        specs: { weight: 'ตามระเบียบ ปณท', size: 'ตามมาตรฐานขนาดพัสดุ', sla: 'มาตรฐานคุณภาพบริการ', rate: 'ตามประกาศอัตราทางการ' },
        blocks: [
          pdfBlock
        ],
        version_history: [
          {
            timestamp: new Date().toISOString(),
            updated_by: 'Batch PDF Ingestion',
            previous_name: extracted.autoTitle || file.name,
            previous_summary: extracted.subject || ''
          }
        ],
        active: true,
        order: state.services.length + 1 + i,
        created_at: new Date().toISOString()
      };

      try {
        const docRef = await addDoc(collection(db, 'categories'), {
          ...newDoc,
          created_at: serverTimestamp()
        });
        if (docRef && docRef.id) newDoc.id = docRef.id;
      } catch (syncErr) {
        newDoc.id = 'announcement_' + Date.now() + '_' + i;
        newDoc.isLocalFallback = true;
      }

      state.services.push(newDoc);
      successCount++;
    } catch (err) {
      console.error('Error processing ' + file.name + ':', err);
    }
  }

  // Update local cache & UI
  try {
    localStorage.setItem('dept_services_cache', JSON.stringify(state.services));
  } catch (e) {}

  if (pdfDropzone) pdfDropzone.style.display = 'flex';
  if (pdfProcessingState) pdfProcessingState.style.display = 'none';
  if (pdfFileInput) pdfFileInput.value = '';
  pdfIngestionModal.classList.remove('active');

  renderServicesView();
  renderSidebarList();
  showToast(`🎉 นำเข้าและสร้างการ์ดเอกสารสำเร็จทั้งหมด ${successCount} รายการเรียบร้อยแล้ว!`, 'success');
}

window.isPdfShadingActive = true;
window.togglePdfShadingMode = () => {
  window.isPdfShadingActive = !window.isPdfShadingActive;
  document.querySelectorAll('.pdf-highlight-overlay').forEach(layer => {
    layer.classList.toggle('hidden', !window.isPdfShadingActive);
  });
  const btn = document.getElementById('btn-toggle-pdf-shading');
  if (btn) {
    btn.innerHTML = window.isPdfShadingActive ? 
      '<i data-lucide="sparkles" style="width: 11px; height: 11px;"></i> แรเงาตำแหน่ง (เปิด)' : 
      '<i data-lucide="eye-off" style="width: 11px; height: 11px;"></i> แรเงาตำแหน่ง (ปิด)';
    lucide.createIcons();
  }
};

window.focusFieldFromShadedZone = (fieldId) => {
  const el = document.getElementById(fieldId);
  if (el) {
    el.focus();
    el.classList.add('flash-field-highlight');
    setTimeout(() => el.classList.remove('flash-field-highlight'), 1200);
    showToast(`🔍 ชี้ตำแหน่งข้อมูล: ${el.labels?.[0]?.innerText || fieldId}`, 'info');
  }
};

// Zero-scroll jump highlight: Only activates visual glow without modifying scroll positions!
window.highlightPdfZone = (zoneClass) => {
  document.querySelectorAll('.pdf-shaded-zone').forEach(z => z.classList.remove('active'));
  document.querySelectorAll(`.pdf-shaded-zone.${zoneClass}`).forEach(z => {
    z.classList.add('active');
  });
};

window.unhighlightPdfZone = () => {
  document.querySelectorAll('.pdf-shaded-zone').forEach(z => z.classList.remove('active'));
};

async function renderPdfPreviewPages(file) {
  const container = document.getElementById('diff-pdf-pages-container');
  const badge = document.getElementById('diff-pdf-page-count-badge');
  if (!container || !file) return;

  container.innerHTML = `
    <div style="color: var(--text-secondary); padding: 40px 20px; text-align: center;">
      <div class="loading-spinner" style="width: 24px; height: 24px; margin: 0 auto 12px;"></div>
      กำลังโหลดหน้าเอกสารต้นฉบับ (PDF)...
    </div>
  `;

  try {
    const arrayBuffer = await file.arrayBuffer();
    const loadingTask = pdfjsLib.getDocument({
      data: arrayBuffer,
      cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',
      cMapPacked: true
    });
    const pdf = await loadingTask.promise;
    
    if (badge) {
      badge.innerHTML = `
        <span style="margin-right: 6px;">เอกสาร ${pdf.numPages} หน้า</span>
        <button type="button" class="btn btn-secondary" id="btn-toggle-pdf-shading" style="font-size: 0.68rem; padding: 2px 7px; color: #ffd60a; border-color: rgba(255,214,10,0.4); background: rgba(255,214,10,0.1);" onclick="window.togglePdfShadingMode()">
          <i data-lucide="sparkles" style="width: 11px; height: 11px;"></i> แรเงาตำแหน่ง (เปิด)
        </button>
      `;
    }
    container.innerHTML = '';

    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
      const page = await pdf.getPage(pageNum);
      const viewport = page.getViewport({ scale: 1.25 });

      const pageCard = document.createElement('div');
      pageCard.style.cssText = 'width: 100%; display: flex; flex-direction: column; align-items: center; gap: 4px; margin-bottom: 12px;';
      
      const pageLabel = document.createElement('div');
      pageLabel.style.cssText = 'font-size: 0.74rem; color: #ffd60a; font-weight: 700; align-self: flex-start; margin-left: 6px; display: flex; align-items: center; justify-content: space-between; width: 100%;';
      pageLabel.innerHTML = `
        <span>📄 หน้าที่ ${pageNum} จากทั้งหมด ${pdf.numPages} หน้า</span>
        <span style="font-size: 0.68rem; color: var(--text-secondary); font-weight: normal;">💡 คลิกที่แถบสีเพื่อชี้ไปยังช่องข้อมูล</span>
      `;

      const wrapper = document.createElement('div');
      wrapper.className = 'diff-pdf-page-wrapper';

      const canvas = document.createElement('canvas');
      canvas.className = 'diff-pdf-page-canvas';
      const context = canvas.getContext('2d');
      canvas.height = viewport.height;
      canvas.width = viewport.width;

      await page.render({ canvasContext: context, viewport: viewport }).promise;

      // Overlay with interactive shaded zones that link 1-to-1 with extracted fields
      const overlay = document.createElement('div');
      overlay.className = `pdf-highlight-overlay ${window.isPdfShadingActive === false ? 'hidden' : ''}`;
      overlay.innerHTML = `
        <div class="pdf-shaded-zone zone-ref" onclick="window.focusFieldFromShadedZone('diff-extracted-ref')" title="คลิกเพื่อไปที่ช่อง: เลขที่หนังสือ (${currentIngestedPdfData?.refNo || 'ปณท'})">
          <span class="pdf-shaded-tag">📌 ${currentIngestedPdfData?.refNo ? currentIngestedPdfData.refNo : 'เลขที่หนังสือ'}</span>
        </div>
        <div class="pdf-shaded-zone zone-date" onclick="window.focusFieldFromShadedZone('diff-extracted-date')" title="คลิกเพื่อไปที่ช่อง: วันที่เอกสาร">
          <span class="pdf-shaded-tag">📅 วันที่เอกสาร</span>
        </div>
        <div class="pdf-shaded-zone zone-title" onclick="window.focusFieldFromShadedZone('diff-extracted-title')" title="คลิกเพื่อไปที่ช่อง: ชื่อเรื่อง / คำสั่ง">
          <span class="pdf-shaded-tag">🎯 ชื่อเรื่อง / สั่งการ</span>
        </div>
        <div class="pdf-shaded-zone zone-body" onclick="window.focusFieldFromShadedZone('diff-after-summary')" title="คลิกเพื่อไปที่ช่อง: สาระสำคัญ & แนวทางปฏิบัติ">
          <span class="pdf-shaded-tag">📋 สาระสำคัญ & วิธีปฏิบัติ</span>
        </div>
      `;

      wrapper.appendChild(canvas);
      wrapper.appendChild(overlay);

      pageCard.appendChild(pageLabel);
      pageCard.appendChild(wrapper);
      container.appendChild(pageCard);
    }
    lucide.createIcons();
  } catch (err) {
    console.error('Render PDF preview error:', err);
    container.innerHTML = `
      <div style="color: var(--apple-red); padding: 20px; text-align: center; font-size: 0.8rem;">
        ไม่สามารถแสดงหน้าพรีวิวได้: ${err.message}
      </div>
    `;
  }
}

function getFormattedThaiDate(dateIsoStr) {
  if (!dateIsoStr) return '';
  try {
    const parts = dateIsoStr.split('-');
    if (parts.length === 3) {
      const day = parseInt(parts[2], 10);
      const monthNames = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      const month = monthNames[parseInt(parts[1], 10) - 1] || '';
      const year = parseInt(parts[0], 10) > 2400 ? parseInt(parts[0], 10) : parseInt(parts[0], 10) + 543;
      return `${day} ${month} ${year}`;
    }
  } catch (e) {}
  return dateIsoStr;
}

function buildSyncedSummaryText() {
  const ref = diffExtractedRef ? diffExtractedRef.value.trim() : '';
  const dateIso = diffExtractedDate ? diffExtractedDate.value : '';
  const title = diffExtractedTitle ? diffExtractedTitle.value.trim() : '';
  const dateThai = getFormattedThaiDate(dateIso);

  let parts = [];
  if (ref) parts.push(`บันทึก ${ref}`);
  if (dateThai) parts.push(`ลว. ${dateThai}`);
  if (title) parts.push(title);

  return parts.join(' ') || title || 'บันทึกสั่งการและแนวทางปฏิบัติการให้บริการ';
}

window.resyncSummaryFromTopFields = () => {
  const summaryEl = document.getElementById('diff-after-summary');
  if (summaryEl) {
    summaryEl.value = buildSyncedSummaryText();
    showToast('🔄 ซิงค์ข้อความตาม 3 ช่องด้านบนเรียบร้อยแล้ว', 'info');
  }
};

function findDuplicateImport(data) {
  if (!data) return null;

  const cleanRef = (data.refNo || '').replace(/[\s\(\)\/\.-]/g, '').toLowerCase();
  const cleanTitle = (data.subject || data.autoTitle || '').trim().toLowerCase();

  for (const s of state.services) {
    // 1. Check if ref number matches
    if (cleanRef && cleanRef.length >= 4) {
      const sSum = (s.summary || '').replace(/[\s\(\)\/\.-]/g, '').toLowerCase();
      const sDesc = (s.description || '').replace(/[\s\(\)\/\.-]/g, '').toLowerCase();
      const sName = (s.name || '').replace(/[\s\(\)\/\.-]/g, '').toLowerCase();

      if (sSum.includes(cleanRef) || sDesc.includes(cleanRef) || sName.includes(cleanRef)) {
        return {
          service: s,
          matchType: 'ref',
          matchValue: data.refNo,
          message: `พบเลขที่บันทึก "${data.refNo}" ในการ์ด "${s.name}"`
        };
      }

      // Check in blocks
      if (Array.isArray(s.blocks)) {
        for (const b of s.blocks) {
          const bTitle = (b.title || '').replace(/[\s\(\)\/\.-]/g, '').toLowerCase();
          if (bTitle.includes(cleanRef)) {
            return {
              service: s,
              matchType: 'ref',
              matchValue: data.refNo,
              message: `พบบันทึกคำสั่ง "${data.refNo}" แนบอยู่ในการ์ด "${s.name}" (${b.title})`
            };
          }
          if (Array.isArray(b.data)) {
            for (const item of b.data) {
              const itemStr = (typeof item === 'string' ? item : (item.title || item.desc || '')).replace(/[\s\(\)\/\.-]/g, '').toLowerCase();
              if (itemStr.includes(cleanRef)) {
                return {
                  service: s,
                  matchType: 'ref',
                  matchValue: data.refNo,
                  message: `พบการอ้างอิง "${data.refNo}" ในรายละเอียดของการ์ด "${s.name}"`
                };
              }
            }
          }
        }
      }
    }

    // 2. Check if title / subject matches closely
    if (cleanTitle && cleanTitle.length >= 12) {
      const sSum = (s.summary || '').toLowerCase();
      const sDesc = (s.description || '').toLowerCase();
      const sName = (s.name || '').toLowerCase();
      
      if (sSum.includes(cleanTitle) || sDesc.includes(cleanTitle) || sName.includes(cleanTitle)) {
        return {
          service: s,
          matchType: 'title',
          matchValue: data.subject,
          message: `พบหัวข้อเรื่องที่ตรงกันในการ์ด "${s.name}"`
        };
      }

      if (Array.isArray(s.blocks)) {
        for (const b of s.blocks) {
          const bTitle = (b.title || '').toLowerCase();
          if (bTitle.includes(cleanTitle)) {
            return {
              service: s,
              matchType: 'title',
              matchValue: data.subject,
              message: `พบหัวข้อบันทึกที่ตรงกันในการ์ด "${s.name}"`
            };
          }
        }
      }
    }
  }

  return null;
}

function openDiffConfirmationModal(data) {
  if (!data) return;

  const dup = findDuplicateImport(data);
  const dupAlertEl = document.getElementById('diff-duplicate-alert');

  if (dup) {
    if (!data.matchedServiceId || data.matchedServiceId === 'NEW_ANNOUNCEMENT') {
      data.matchedServiceId = dup.service.id;
    }

    if (dupAlertEl) {
      dupAlertEl.style.display = 'block';
      dupAlertEl.innerHTML = `
        <div style="background: rgba(255, 69, 58, 0.15); border: 1px solid rgba(255, 69, 58, 0.45); border-radius: var(--radius-md); padding: 12px 14px; display: flex; align-items: flex-start; gap: 10px; margin-bottom: 4px;">
          <i data-lucide="alert-triangle" style="color: #ff453a; width: 22px; height: 22px; flex-shrink: 0; margin-top: 2px;"></i>
          <div style="flex: 1;">
            <div style="font-weight: 700; color: #ff453a; font-size: 0.92rem; margin-bottom: 3px;">
              ⚠️ แจ้งเตือน: เอกสาร/บันทึกนี้เคยถูกนำเข้าสู่ระบบแล้ว!
            </div>
            <div style="font-size: 0.82rem; color: #fff; line-height: 1.45;">
              ${dup.message}<br>
              <span style="color: #ffd60a; font-size: 0.78rem;">📌 ระบบได้เลือกการ์ด <strong>"${dup.service.name}"</strong> ให้อัตโนมัติ ท่านสามารถเลือกอัปเดตทับ หรือเพิ่มเป็นบันทึกอีกฉบับได้</span>
            </div>
          </div>
        </div>
      `;
    }

    showToast(`⚠️ แจ้งเตือน: เอกสารนี้เคยนำเข้าในการ์ด "${dup.service.name}" แล้ว`, 'warning');
  } else {
    if (dupAlertEl) {
      dupAlertEl.style.display = 'none';
      dupAlertEl.innerHTML = '';
    }
  }

  // Pre-select detected category in the Category Switcher
  const diffNewCatSelect = document.getElementById('diff-new-category-type');
  if (diffNewCatSelect) {
    diffNewCatSelect.value = data.detectedCategory || 'news';
  }

  const catLabels = {
    'coldchain': '❄️ FUZE POST',
    'international': '🌐 ระหว่างประเทศ',
    'domestic': '🇹🇭 ในประเทศ',
    'promotions': '🎁 โปรโมชั่น & ส่วนลด',
    'news': '📢 ศูนย์ข่าว & ประกาศ'
  };

  const detectedLabel = catLabels[data.detectedCategory] || 'หมวดข่าว';

  const hasMatchedService = Boolean(data.matchedServiceId && data.matchedServiceId !== 'NEW_ANNOUNCEMENT' && state.services.some(s => s.id === data.matchedServiceId));

  const optionsHtml = state.services.map(s => {
    const isMatched = (s.id === data.matchedServiceId);
    const catBadge = catLabels[s.category_type] || s.category_type || '';
    return `
      <option value="${s.id}" ${isMatched ? 'selected' : ''}>
        ${s.name} (${catBadge}) ${isMatched ? '👈 [AI แนะนำ]' : ''}
      </option>
    `;
  }).join('');

  // Populate Target Service Dropdown with AI auto-selection
  diffTargetService.innerHTML = `
    <optgroup label="📋 การ์ดบริการปัจจุบันที่มีอยู่ในระบบ">
      ${optionsHtml}
    </optgroup>
    <option value="NEW_ANNOUNCEMENT" ${!hasMatchedService ? 'selected' : ''}>
      ✨ [+ แยกสร้างเป็นการ์ดใหม่ใน ${detectedLabel}]
    </option>
  `;

  if (hasMatchedService) {
    diffTargetService.value = data.matchedServiceId;
  } else {
    diffTargetService.value = 'NEW_ANNOUNCEMENT';
  }

  diffExtractedTitle.value = data.subject || data.autoTitle || '';
  diffExtractedDate.value = data.docDate || new Date().toISOString().split('T')[0];
  diffExtractedRef.value = data.refNo || '';

  renderDiffPanels();
  renderPdfPreviewPages(data.file);

  // Live Auto-Sync: Modifying Title, Date, or Ref Number instantly recalculates and syncs summary
  const syncSummaryHandler = () => {
    const summaryEl = document.getElementById('diff-after-summary');
    if (summaryEl) {
      summaryEl.value = buildSyncedSummaryText();
    }
  };

  diffExtractedTitle.oninput = syncSummaryHandler;
  diffExtractedDate.onchange = syncSummaryHandler;
  diffExtractedRef.oninput = syncSummaryHandler;
  diffTargetService.onchange = () => renderDiffPanels();

  const bindHighlight = (inputEl, zoneClass) => {
    if (!inputEl) return;
    inputEl.onmouseenter = inputEl.onfocus = () => window.highlightPdfZone(zoneClass);
    inputEl.onmouseleave = inputEl.onblur = () => window.unhighlightPdfZone();
  };

  bindHighlight(diffExtractedRef, 'zone-ref');
  bindHighlight(diffExtractedDate, 'zone-date');
  bindHighlight(diffExtractedTitle, 'zone-title');
  setTimeout(() => {
    bindHighlight(document.getElementById('diff-after-summary'), 'zone-body');
    bindHighlight(document.getElementById('diff-after-checklist'), 'zone-body');
  }, 250);

  diffConfirmationModal.classList.add('active');
  lucide.createIcons();
}

function renderDiffPanels() {
  if (!currentIngestedPdfData) return;
  const targetId = diffTargetService.value;
  const isNew = targetId === 'NEW_ANNOUNCEMENT';
  const existingService = state.services.find(s => s.id === targetId);

  const newCatBox = document.getElementById('diff-new-category-box');
  if (newCatBox) {
    newCatBox.style.display = isNew ? 'block' : 'none';
  }

  // Left Panel: Before (Current)
  if (isNew || !existingService) {
    diffBeforeServiceName.innerText = '(ยังไม่มีข้อมูลเดิมในระบบ)';
    diffBeforeContent.innerHTML = `
      <div style="text-align: center; color: var(--text-tertiary); padding: 40px 10px;">
        <i data-lucide="plus-circle" style="width: 32px; height: 32px; margin-bottom: 8px; color: var(--apple-blue);"></i>
        <p>สร้างเป็นการ์ดประกาศใหม่ ไม่กระทบข้อมูลเดิม</p>
      </div>
    `;
  } else {
    diffBeforeServiceName.innerText = existingService.name;
    const specs = existingService.specs || {};
    diffBeforeContent.innerHTML = `
      <div class="diff-field-box">
        <div class="diff-field-label">📌 คำอธิบายย่อปัจจุบัน:</div>
        <div class="diff-field-value">${existingService.summary || '-'}</div>
      </div>
      <div class="diff-field-box">
        <div class="diff-field-label">⚖️ น้ำหนัก / ขนาด:</div>
        <div class="diff-field-value">${specs.weight || '-'} | ${specs.size || '-'}</div>
      </div>
      <div class="diff-field-box">
        <div class="diff-field-label">⏱️ ระยะเวลานำจ่าย (SLA):</div>
        <div class="diff-field-value">${specs.sla || '-'}</div>
      </div>
      <div class="diff-field-box">
        <div class="diff-field-label">💰 อัตราค่าบริการ:</div>
        <div class="diff-field-value" style="color: var(--apple-mint);">${specs.rate || '-'}</div>
      </div>
    `;
  }

  // Right Panel: After (Extracted from PDF - Editable with Live Sync)
  const existingSpecs = existingService?.specs || {};
  diffAfterContent.innerHTML = `
    <div class="form-group" style="margin-bottom: 10px;">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
        <label class="form-label" style="font-size: 0.76rem; color: var(--apple-mint); margin-bottom: 0;">
          📝 คำอธิบายย่อ (🔗 ซิงค์อัตโนมัติตาม 3 ช่องด้านบน):
        </label>
        <button type="button" class="btn btn-secondary" onclick="window.resyncSummaryFromTopFields()" style="font-size: 0.68rem; padding: 2px 6px; height: 20px;" title="กดเพื่อสร้างข้อความใหม่จากเลขที่/วันที่/ชื่อเรื่อง">
          🔄 ซิงค์ใหม่
        </button>
      </div>
      <textarea id="diff-after-summary" class="form-control" rows="2" style="font-size: 0.82rem;">${buildSyncedSummaryText()}</textarea>
    </div>
    <div class="form-row" style="margin-bottom: 10px;">
      <div class="form-group">
        <label class="form-label" style="font-size: 0.76rem;">⚖️ พิกัดน้ำหนัก:</label>
        <input type="text" id="diff-after-weight" class="form-control" style="font-size: 0.82rem;" value="${existingSpecs.weight || 'ตามข้อกำหนดบันทึกสั่งการ ปณท'}">
      </div>
      <div class="form-group">
        <label class="form-label" style="font-size: 0.76rem;">📏 มิติขนาด:</label>
        <input type="text" id="diff-after-size" class="form-control" style="font-size: 0.82rem;" value="${existingSpecs.size || 'ตามมาตรฐานขนาดพัสดุ ปณท'}">
      </div>
    </div>
    <div class="form-row" style="margin-bottom: 10px;">
      <div class="form-group">
        <label class="form-label" style="font-size: 0.76rem;">⏱️ ระยะเวลานำจ่าย (SLA):</label>
        <input type="text" id="diff-after-sla" class="form-control" style="font-size: 0.82rem;" value="${existingSpecs.sla || '1 - 2 วันทำการ'}">
      </div>
      <div class="form-group">
        <label class="form-label" style="font-size: 0.76rem; color: var(--apple-mint);">💰 อัตราค่าบริการ / ข้อกำหนดใหม่:</label>
        <input type="text" id="diff-after-rate" class="form-control" style="font-size: 0.82rem;" value="${existingSpecs.rate || 'ตามอัตราในบันทึกสั่งการล่าสุด'}">
      </div>
    </div>
    <div class="form-group" style="margin-bottom: 10px;">
      <label class="form-label" style="font-size: 0.76rem;">📋 สาระสำคัญ / รายการข้อปฏิบัติ (Checklist):</label>
      <textarea id="diff-after-checklist" class="form-control" rows="3" style="font-size: 0.82rem;">${currentIngestedPdfData.keyPoints.join('\n')}</textarea>
    </div>
  `;

  lucide.createIcons();
}

// Version History & 1-Click Rollback Handlers
function openVersionHistoryModal(serviceId) {
  const service = state.services.find(s => s.id === serviceId);
  if (!service) return;

  historyModalSubtitle.innerText = `ประวัติการแก้ไขของ: ${service.name}`;
  const history = service.version_history || [];

  if (history.length === 0) {
    versionHistoryList.innerHTML = `
      <div style="text-align: center; color: var(--text-tertiary); padding: 40px 10px;">
        <i data-lucide="history" style="width: 40px; height: 40px; margin-bottom: 8px; opacity: 0.4;"></i>
        <p>ยังไม่มีประวัติการแก้ไขสำหรับรายการนี้ (เป็นเวอร์ชันต้นฉบับ)</p>
      </div>
    `;
  } else {
    versionHistoryList.innerHTML = history.slice().reverse().map((snap, idx) => `
      <div class="history-timeline-item">
        <div class="history-header">
          <span class="history-badge">Snapshot #${history.length - idx}</span>
          <span class="history-date">${snap.timestamp ? new Date(snap.timestamp).toLocaleString('th-TH') : 'บันทึกอัตโนมัติ'}</span>
        </div>
        <div class="history-details">
          <div><strong>📌 ชื่อรายการเดิม:</strong> ${snap.previous_name || service.name}</div>
          <div><strong>📝 คำอธิบาย:</strong> ${snap.previous_summary || '-'}</div>
          <div><strong>⚖️ อัตรา/สเปก:</strong> ${snap.previous_specs?.rate || '-'}</div>
        </div>
        <div style="display: flex; justify-content: flex-end;">
          <button type="button" class="btn btn-secondary" onclick="rollbackServiceVersion('${service.id}', ${history.length - 1 - idx})" style="font-size: 0.76rem; padding: 4px 10px; color: #64d2ff; border-color: rgba(100, 210, 255, 0.4);">
            <i data-lucide="rotate-ccw"></i> ⏮️ กู้คืนข้อมูลเวอร์ชันนี้ (Rollback)
          </button>
        </div>
      </div>
    `).join('');
  }

  versionHistoryModal.classList.add('active');
  lucide.createIcons();
}

window.rollbackServiceVersion = async (serviceId, snapIndex) => {
  const service = state.services.find(s => s.id === serviceId);
  if (!service || !service.version_history || !service.version_history[snapIndex]) {
    showToast('ไม่พบข้อมูล Snapshot ที่ต้องการกู้คืน', 'danger');
    return;
  }

  if (!confirm('ยืนยัน: ต้องการย้อนกลับไปใช้ข้อมูลใน Snapshot นี้ใช่หรือไม่?')) return;

  const snap = service.version_history[snapIndex];

  // Save current as a new snapshot before rolling back
  const currentSnapshot = {
    timestamp: new Date().toISOString(),
    updated_by: 'Rollback Action',
    previous_name: service.name,
    previous_summary: service.summary,
    previous_specs: service.specs || {},
    previous_blocks: service.blocks || []
  };

  service.name = snap.previous_name || service.name;
  service.summary = snap.previous_summary || service.summary;
  service.specs = snap.previous_specs || service.specs;
  service.blocks = snap.previous_blocks || service.blocks;
  service.version_history.push(currentSnapshot);

  try {
    await setDoc(doc(db, 'categories', service.id), {
      name: service.name,
      summary: service.summary,
      specs: service.specs,
      blocks: service.blocks,
      version_history: service.version_history,
      updated_at: serverTimestamp()
    }, { merge: true });
  } catch (err) {
    console.warn('Sync rollback to cloud notice:', err.message);
  }

  versionHistoryModal.classList.remove('active');
  if (state.activeService?.id === service.id) {
    state.activeService = service;
    renderServiceDetail(service);
  }
  renderServicesView();
  showToast('⏮️ กู้คืนข้อมูลเดิมเรียบร้อยแล้ว!', 'success');
};

// ==========================================================================
// 🔄 Re-sync / Re-analyze Service Card from Attached PDF
// ==========================================================================
window.resyncServiceFromAttachedPdf = async (serviceId) => {
  const service = state.services.find(s => s.id === serviceId);
  if (!service) {
    showToast('ไม่พบข้อมูลบริการที่ต้องการรีเฟรช', 'danger');
    return;
  }

  // 1. Locate PDF block in the service
  let pdfLinkObj = null;
  if (Array.isArray(service.blocks)) {
    for (const b of service.blocks) {
      if (b.type === 'pdf_embed') {
        const links = Array.isArray(b.data) ? b.data : (b.data?.links || []);
        if (links.length > 0 && links[0].url) {
          pdfLinkObj = links[0];
          break;
        }
      }
    }
  }

  if (!pdfLinkObj || !pdfLinkObj.url || pdfLinkObj.url === '#') {
    showToast('การ์ดบริการนี้ยังไม่มีไฟล์ PDF แนบอยู่ ไม่สามารถสแกนเนื้อหาใหม่ได้', 'warning');
    return;
  }

  showToast(`🔍 กำลังอ่านและวิเคราะห์ไฟล์ PDF "${pdfLinkObj.title || 'เอกสารแนบ'}"...`, 'info');

  try {
    let fileBlobOrUrl = pdfLinkObj.url;
    let fileObj = null;

    // Fetch PDF bytes as ArrayBuffer directly for 100% reliable PDF.js parsing
    let arrayBuffer = null;
    if (typeof fileBlobOrUrl === 'string') {
      try {
        const res = await fetch(fileBlobOrUrl);
        arrayBuffer = await res.arrayBuffer();
      } catch (fetchErr) {
        console.warn('Direct fetch error:', fetchErr);
      }
    }

    const rawText = await extractTextFromPdf(arrayBuffer || fileBlobOrUrl);
    if (!rawText || rawText.trim().length === 0) {
      showToast('ไม่สามารถดึงข้อความจากไฟล์ PDF ได้', 'warning');
      return;
    }

    const extracted = parseThailandPostMemoText(rawText, pdfLinkObj.url || pdfLinkObj.title || service.name);

    currentIngestedPdfData = {
      file: arrayBuffer ? new Blob([arrayBuffer], { type: 'application/pdf' }) : fileBlobOrUrl,
      fileName: pdfLinkObj.title || `${service.name}.pdf`,
      ...extracted,
      matchedServiceId: service.id // Force target to this exact service
    };

    // Close detail modal and open the Diff & Comparison Wizard
    if (detailModal) detailModal.classList.remove('active');
    openDiffConfirmationModal(currentIngestedPdfData);

    // Auto-select 'replace' mode for resync
    setTimeout(() => {
      const replaceRadio = document.getElementById('import-mode-replace');
      if (replaceRadio) replaceRadio.checked = true;
    }, 100);

    showToast('✨ สแกนข้อมูลจาก PDF สำเร็จแล้ว! ตรวจสอบความถูกต้องและกดยืนยันเพื่ออัปเดต', 'success');
  } catch (err) {
    console.error('Resync PDF Error:', err);
    showToast(`เกิดข้อผิดพลาดในการอ่าน PDF: ${err.message}`, 'danger');
  }
};

